-- ════════════════════════════════════════════════════════
-- 244 — Huitième recensement : quinze maisons, dont Dalay et
--       Tabacosta (lots d'écriture 11, 13 et 14)
-- ────────────────────────────────────────────────────────
-- D'OÙ ELLES VIENNENT. Comme la 239 à la 243 : des noms que le marché
-- vend et que l'atlas n'avait pas, passés par le tri, le contradicteur,
-- le rédacteur, la relecture et la traduction.
--   Rép. dominicaine  Hemmys (ABAM, Villa Mella), German Engineered
--                     Cigars (Intercigar, Tamboril ; Tabacalera Tambor,
--                     Estelí), Dalay (Zauberberg, Santiago), Casa de
--                     Garcia et Dominican Estates (Tabacalera de García,
--                     La Romana), Dos Jotas (fabrique de Chico Rivas,
--                     Tamboril)
--   Nicaragua         El Galan, Tabacosta et Tambor Essence (usines
--                     propres), H.R. (La Corona), Omar Rodriguez
--                     (Diamante), à Estelí ; Helvada, Spartanos et
--                     Teatro del Mundo
--   Honduras          Legado (CLE Cigar Company, Danlí)
--
-- ── LE SILENCE ÉCRIT ────────────────────────────────────
-- Trois fiches : Helvada, Spartanos et Teatro del Mundo. Le
-- propriétaire est identifié et le pays de roulage attesté ; la maison
-- ne nomme pas sa fabrique (décision du 23 septembre).
--
-- ── LES MAISONS À PLUSIEURS MARQUES ─────────────────────
-- Dalay et Tabacosta reçoivent une fiche de maison (décision du
-- 24 septembre) : Ferruh Karakasli est une ligne de Dalay, Manuel Alonso
-- une ligne de Tabacosta.
--
-- ── CE QUE LA RELECTURE A TRANCHÉ ───────────────────────
-- German Engineered Cigars se range en République dominicaine : trois
-- lignes sur cinq, dont RVGN, y sont roulées, chez Intercigar. H.R.
-- garde ce nom ; HR et Hirochi Robaina sont les noms sous lesquels on la
-- cherche. Dos Jotas sort du silence : Momentohumo et André Dias la
-- disent roulée chez Chico Rivas, à Tamboril, où elle est née en 1999 ;
-- la fabrique s'écrit attribuée, la maison ne la nomme pas.
-- Les entrées au catalogue d'un détaillant ne sont pas des fondations :
-- le 28 septembre 2005 de Dominican Estates, le 19 avril 2021 de
-- Spartanos et le 21 avril 2020 d'Omar Rodriguez restent hors des dates
-- de la maison. Teatro del Mundo est une création de Schuster selon
-- Tabakhaus Schall ; Cigarworld.de et Falkum.de ne le donnent que pour
-- importateur. Les arômes de vanille et de café venaient d'avis de
-- clients : reste le chocolat, que dit Falkum.de. Ce qui ne reposait que
-- sur des pages illisibles (Halfwheel payant, Mike's Cigars fermé aux
-- robots) est sorti ; une page payante n'est citée que par son titre.
-- Traductions : le 第一 de « le premier cigare » (German Engineered
-- Cigars) devient 头一款.
--
-- ── DIVERGENCES ÉCRITES ─────────────────────────────────
-- Helvada : la bague « Hecho a mano » de sa 51, que la maison lit comme
-- une tripe façonnée à la machine sous une cape roulée à la main ;
-- Cigarworld.de vend la Medio Filler Medio Tiempo entièrement roulée à
-- la main. Dalay : Zauberberg, usine propre selon la maison, coentreprise
-- avec des partenaires dominicains selon Halfwheel. Tabacosta : fondée
-- en 2002 ou en 2012, installée au Nicaragua en 2004 ou en 2014, selon
-- Momentohumo.com ou Halfwheel. German Engineered Cigars : deux
-- fondateurs selon la maison, trois selon Cigar Coop et Cigar Dojo.
-- Casa de Garcia : fondée par Pepe García selon Onlineshop-Helgoland,
-- quand Cigarworld.de ne lui attribue que la fabrique.
--
-- Rejouable : INSERT … ON DUPLICATE KEY UPDATE ; le `brands` des pays
-- touchés est relu en base et réécrit en littéral ; sceaux `machine`.
-- ════════════════════════════════════════════════════════

-- ── Hemmys ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Hemmys',
        'dominican',
        '2019 — Hemmy Garcia, Berlin',
        'Chez ABAM Cigars S.R.L. (Matías Maragoto), Villa Mella, Santo Domingo Norte (République dominicaine)',
        'hemmys.de « Hemmy''s Zigarren – Berlin » (consulté le 25 septembre 2026, dit la maison : Hemmy Garcia né à Cuba, boutique Hemmy''s finest Cigars & More ouverte à Berlin en 2008, cigares Hemmys roulés à la main chez ABAM Cigars, à Santo Domingo) ; hemmys.de « Über uns » (consulté le 25 septembre 2026, dit la maison : formation de torcedor et de contrôleur qualité à la manufacture H. Upmann, à La Havane) ; startupvalley.news « Hemmy Garcia: Wie ein Berliner Entrepreneur die Zigarre zukunftsfähig macht » (en allemand, août 2019 : apprentissage de commerce chez Villiger & Söhne, à Waldshut-Tiengen, boutique de Berlin-Frohnau ouverte vers 2008, marque Hemmys lancée début 2019) ; smokersplanet.de « Hemmy Garcia: Cuba im Blut und Berlin als heimischer Standort » (en allemand, 4 février 2019 : naissance à Cuba, boutique de Berlin-Frohnau ouverte plus de dix ans avant l''article) ; cigarworld.de « Hemmys » (consulté le 25 septembre 2026 : commande de Hemmy Garcia roulée à la fabrique ABAM Cigars de Matías Maragoto, en République dominicaine ; ligne classique — cape du Nicaragua, sous-cape du Pérou, tripe de ligero et de double ligero du Nicaragua et de République dominicaine, force medium — au catalogue depuis le 5 avril 2019 ; séries Hemmys Maduro et Hemmys Linea Secreta, vitolas Edicion Limitada encore listées) ; cigarworld.de « Hemmys Linea Secreta » (consulté le 25 septembre 2026 : ligne succédant à une Edición Limitada arrêtée, roulée par Matías Maragoto à la Tabacalera ABAM, tabac dominicain, mélange non divulgué, cinq vitolas) ; cigarjournal.com « ABAM Cigars: Villiger''s Unknown Factory » (date non précisée : fabrique ABAM à Santo Domingo dirigée par le Cubain exilé Matías Maragoto, roulant notamment Bock y Ca.) ; cigardojo.com « D''Crossier Golden Blend Reserva Magnum Review » (avril 2021 : D''Crossier roulée depuis 2017 chez ABAM Cigars S.R.L., en République dominicaine)',
        NULL,
        'Hemmy Garcia naît à Cuba et se forme comme torcedor et contrôleur qualité à la manufacture H. Upmann, à La Havane, dit la maison. Il fait aussi un apprentissage de commerce chez Villiger Söhne, à Waldshut-Tiengen, dit Startupvalley.news, et ouvre en 2008 à Berlin-Frohnau sa boutique, Hemmy''s finest Cigars & More.

Lancée début 2019, sa marque Hemmys est roulée à la main chez ABAM Cigars S.R.L., la fabrique de Matías Maragoto à Santo Domingo, dit la maison ; ABAM roule aussi Bock y Ca. et D''Crossier. Cigarworld.de vend la ligne classique depuis le 5 avril 2019 : cape du Nicaragua, sous-cape du Pérou, tripe de ligero et de double ligero du Nicaragua et de République dominicaine, de force medium.

En septembre 2026, le catalogue compte aussi une ligne Maduro et la Linea Secreta, que Cigarworld.de présente comme la suite de l''Edición Limitada : un mélange tenu secret à base de tabac dominicain, roulé par Matías Maragoto, en cinq vitolas, de la Petit Lanceros à la Don Manuel.',
        '[{"name":"Hemmys","color":"#A0522D","force":"Medium","wrapper":"Nicaragua","vitolas":[],"story":"Cape du Nicaragua, sous-cape du Pérou, tripe de ligero et de double ligero du Nicaragua et de République dominicaine, de force medium, dit Cigarworld.de."},{"name":"Hemmys Maduro","color":"#4A3728","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Ligne maduro du catalogue, dit Cigarworld.de."},{"name":"Hemmys Linea Secreta","color":"#A0522D","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Présentée par Cigarworld.de comme la suite de l''Edición Limitada ; mélange tenu secret à base de tabac dominicain, en cinq vitolas, de la Petit Lanceros à la Don Manuel."}]',
        'Hemmy Garcia was born in Cuba and trained as a torcedor and quality controller at the H. Upmann factory in Havana, says the house. He also completed a commercial apprenticeship with Villiger Söhne, in Waldshut-Tiengen, says Startupvalley.news, and in 2008 opened his shop, Hemmy''s finest Cigars & More, in Berlin-Frohnau.

Launched in early 2019, his Hemmys brand is hand-rolled at ABAM Cigars S.R.L., Matías Maragoto''s factory in Santo Domingo, says the house; ABAM also rolls Bock y Ca. and D''Crossier. Cigarworld.de has sold the classic line since 5 April 2019: Nicaraguan wrapper, Peruvian binder, filler of ligero and double ligero from Nicaragua and the Dominican Republic, medium-bodied.

By September 2026, the catalogue also includes a Maduro line and the Linea Secreta, which Cigarworld.de presents as the successor to the Edición Limitada: a blend kept secret, based on Dominican tobacco, rolled by Matías Maragoto, in five vitolas, from the Petit Lanceros to the Don Manuel.',
        '[{"name":"Hemmys","color":"#A0522D","force":"Medium","wrapper":"Nicaragua","vitolas":[],"story":"Nicaraguan wrapper, Peruvian binder, filler of ligero and double ligero from Nicaragua and the Dominican Republic, medium-bodied, says Cigarworld.de."},{"name":"Hemmys Maduro","color":"#4A3728","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Maduro line of the catalogue, says Cigarworld.de."},{"name":"Hemmys Linea Secreta","color":"#A0522D","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Presented by Cigarworld.de as the successor to the Edición Limitada; blend kept secret, based on Dominican tobacco, in five vitolas, from the Petit Lanceros to the Don Manuel."}]',
        'Hemmy Garcia nace en Cuba y se forma como torcedor y controlador de calidad en la fábrica H. Upmann, en La Habana, dice la casa. También realiza un aprendizaje comercial en Villiger Söhne, en Waldshut-Tiengen, dice Startupvalley.news, y en 2008 abre en Berlín-Frohnau su tienda, Hemmy''s finest Cigars & More.

Lanzada a principios de 2019, su marca Hemmys se elabora a mano en ABAM Cigars S.R.L., la fábrica de Matías Maragoto en Santo Domingo, dice la casa; ABAM también elabora Bock y Ca. y D''Crossier. Cigarworld.de vende la línea clásica desde el 5 de abril de 2019: capa de Nicaragua, capote de Perú, tripa de ligero y de double ligero de Nicaragua y de República Dominicana, de fuerza medium.

En septiembre de 2026, el catálogo incluye también una línea Maduro y la Linea Secreta, que Cigarworld.de presenta como la continuación de la Edición Limitada: una mezcla mantenida en secreto a base de tabaco dominicano, elaborada por Matías Maragoto, en cinco vitolas, de la Petit Lanceros a la Don Manuel.',
        '[{"name":"Hemmys","color":"#A0522D","force":"Medium","wrapper":"Nicaragua","vitolas":[],"story":"Capa de Nicaragua, capote de Perú, tripa de ligero y de double ligero de Nicaragua y de República Dominicana, de fuerza medium, dice Cigarworld.de."},{"name":"Hemmys Maduro","color":"#4A3728","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Línea maduro del catálogo, dice Cigarworld.de."},{"name":"Hemmys Linea Secreta","color":"#A0522D","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Presentada por Cigarworld.de como la continuación de la Edición Limitada; mezcla mantenida en secreto a base de tabaco dominicano, en cinco vitolas, de la Petit Lanceros a la Don Manuel."}]',
        'Hemmy Garcia wird auf Kuba geboren und lässt sich in der Fabrik H. Upmann in Havanna zum Torcedor und Qualitätskontrolleur ausbilden, so das Haus. Zudem absolviert er eine kaufmännische Lehre bei Villiger Söhne in Waldshut-Tiengen, so Startupvalley.news, und eröffnet 2008 in Berlin-Frohnau sein Geschäft, Hemmy''s finest Cigars & More.

Seine 2019 gestartete Marke Hemmys wird bei ABAM Cigars S.R.L., der Fabrik von Matías Maragoto in Santo Domingo, von Hand gerollt, so das Haus; ABAM rollt auch Bock y Ca. und D''Crossier. Cigarworld.de verkauft die klassische Linie seit dem 5. April 2019: Deckblatt aus Nicaragua, Umblatt aus Peru, Einlage aus Ligero und Double Ligero aus Nicaragua und der Dominikanischen Republik, Stärke medium.

Im September 2026 umfasst das Sortiment auch eine Maduro-Linie und die Linea Secreta, die Cigarworld.de als Nachfolgerin der Edición Limitada vorstellt: eine geheim gehaltene Mischung auf Basis dominikanischen Tabaks, gerollt von Matías Maragoto, in fünf Vitolas, von der Petit Lanceros bis zur Don Manuel.',
        '[{"name":"Hemmys","color":"#A0522D","force":"Medium","wrapper":"Nicaragua","vitolas":[],"story":"Deckblatt aus Nicaragua, Umblatt aus Peru, Einlage aus Ligero und Double Ligero aus Nicaragua und der Dominikanischen Republik, Stärke medium, so Cigarworld.de."},{"name":"Hemmys Maduro","color":"#4A3728","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Maduro-Linie des Sortiments, so Cigarworld.de."},{"name":"Hemmys Linea Secreta","color":"#A0522D","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Von Cigarworld.de als Nachfolgerin der Edición Limitada vorgestellt; geheim gehaltene Mischung auf Basis dominikanischen Tabaks, in fünf Vitolas, von der Petit Lanceros bis zur Don Manuel."}]',
        '品牌方称，Hemmy Garcia生于古巴，曾在哈瓦那的H. Upmann工厂接受培训，成为torcedor及质检员。据Startupvalley.news报道，他还曾在Waldshut-Tiengen的Villiger Söhne完成商业学徒，并于2008年在Berlin-Frohnau开设了自己的店铺Hemmy''s finest Cigars & More。

品牌方称，Hemmys品牌于2019年初创立，在Matías Maragoto位于圣多明各的工厂ABAM Cigars S.R.L.手工卷制；ABAM同时也卷制Bock y Ca.与D''Crossier。Cigarworld.de自2019年4月5日起销售经典系列：尼加拉瓜茄衣，秘鲁茄套，尼加拉瓜与多米尼加共和国的ligero及double ligero茄芯，力道为medium。

截至2026年9月，产品目录还包括Maduro系列与Linea Secreta；Cigarworld.de将其称为Edición Limitada的后续系列：配方保密，以多米尼加烟叶为基础，由Matías Maragoto卷制，共五种vitola，从Petit Lanceros到Don Manuel。',
        '[{"name":"Hemmys","color":"#A0522D","force":"Medium","wrapper":"尼加拉瓜","vitolas":[],"story":"尼加拉瓜茄衣，秘鲁茄套，尼加拉瓜与多米尼加共和国的ligero及double ligero茄芯，力道为medium，据Cigarworld.de介绍。"},{"name":"Hemmys Maduro","color":"#4A3728","force":null,"wrapper":"未公开","vitolas":[],"story":"产品目录中的maduro系列，据Cigarworld.de介绍。"},{"name":"Hemmys Linea Secreta","color":"#A0522D","force":null,"wrapper":"未公开","vitolas":[],"story":"由Cigarworld.de称为Edición Limitada的后续系列；配方保密，以多米尼加烟叶为基础，共五种vitola，从Petit Lanceros到Don Manuel。"}]',
        'وُلد Hemmy Garcia في كوبا، وتلقى تدريبه ليصبح torcedor ومراقبَ جودة في مصنع H. Upmann بهافانا، بحسب الدار. كما أتمّ تدريبًا تجاريًا لدى Villiger Söhne في Waldshut-Tiengen، بحسب Startupvalley.news، وافتتح عام 2008 متجره Hemmy''s finest Cigars & More في Berlin-Frohnau ببرلين.

أُطلقت علامة Hemmys في مطلع عام 2019، وتُلَفّ يدويًا في ABAM Cigars S.R.L.، مصنع Matías Maragoto في سانتو دومينغو، بحسب الدار؛ وتلف ABAM أيضًا Bock y Ca. وD''Crossier. وتبيع Cigarworld.de الخط الكلاسيكي منذ 5 أبريل 2019: غلاف من نيكاراغوا، ورباط من بيرو، وحشوة من ligero وdouble ligero من نيكاراغوا وجمهورية الدومينيكان، بقوة medium.

بحلول سبتمبر 2026، يضمّ الكتالوج أيضًا خط Maduro وLinea Secreta، التي تقدّمها Cigarworld.de بوصفها امتدادًا لـEdición Limitada: مزيج سرّي قائم على تبغ من جمهورية الدومينيكان، تلفّه Matías Maragoto، في خمسة أشكال vitola، من Petit Lanceros إلى Don Manuel.',
        '[{"name":"Hemmys","color":"#A0522D","force":"Medium","wrapper":"نيكاراغوا","vitolas":[],"story":"غلاف من نيكاراغوا، ورباط من بيرو، وحشوة من ligero وdouble ligero من نيكاراغوا وجمهورية الدومينيكان، بقوة medium، بحسب Cigarworld.de."},{"name":"Hemmys Maduro","color":"#4A3728","force":null,"wrapper":"غير معلن","vitolas":[],"story":"خط maduro ضمن الكتالوج، بحسب Cigarworld.de."},{"name":"Hemmys Linea Secreta","color":"#A0522D","force":null,"wrapper":"غير معلن","vitolas":[],"story":"تقدّمها Cigarworld.de بوصفها امتدادًا لـEdición Limitada؛ مزيج سرّي قائم على تبغ من جمهورية الدومينيكان، في خمسة أشكال vitola، من Petit Lanceros إلى Don Manuel."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── El Galan ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('El Galan',
        'nicaragua',
        '2013 — Felix A. Mesa, Estelí',
        'Usine propre — El Galan Cigars S.A., Estelí',
        'cuencacigars.com « Don''t Underestimate El Galan Cigars » (16 janvier 2016 : lignes El Galan Maduro, Reserva Especial Connecticut et Doña Nieves, en Gran Reserva et Sentimiento) ; cigarworld.de « El Galan » (consulté le 25 septembre 2026 : lignes Reserva Especial en cape oscuro, corsée, Connecticut en puro nicaraguayen, plus douce, Maduro en cape brésilienne, et Tabaco de la Casa, entrée de gamme) ; arturofuente.com « Arturo Fuente Cigars back in Nicaragua! » (consulté le 25 septembre 2026, dit la maison : annonce du 26 janvier 2018 à Puro Sabor d''une nouvelle fabrique à Estelí, la Gran Fabrica de Tabacos La Bella y La Bestia, confiée à Felix Mesa, propriétaire d''El Galan Cigars) ; stogiepress.com « Fuente Coming Back To Esteli, Nicaragua – Love of the People » (1er février 2018 : confirme l''annonce du 26 janvier 2018 et le rôle de Felix Mesa) ; halfwheel.com « Felix Mesa Departs Arturo Fuente''s Nicaragua Operations, Returns to El Galan Cigars » (2023, page payante lue par son titre : Felix Mesa quitte les opérations nicaraguayennes d''Arturo Fuente et revient à El Galan Cigars) ; cigaraficionado.com « El Galan Launching Vegas del Purial in October » (14 septembre 2018 : grands-parents paternels de Felix Mesa, Felipe et Caridad Mesa, cultivateurs de tabac dans la province cubaine de Las Villas ; El Galan Cigars fondée en 2013, nommée d''après le surnom du grand-père, toujours élégamment vêtu ; cigares roulés à El Galan Cigars S.A., au Nicaragua ; Vegas del Purial — cape Sumatra d''Équateur, sous-cape et tripe nicaraguayennes — lancée en octobre 2018)',
        NULL,
        'Les grands-parents paternels de Felix A. Mesa, Felipe et Caridad Mesa, cultivaient le tabac dans la province cubaine de Las Villas. Mesa fonde El Galan Cigars en 2013 et lui donne le surnom que portait à Cuba son grand-père, toujours élégamment vêtu ; ses cigares se roulent dans sa propre fabrique, El Galan Cigars S.A., à Estelí, au Nicaragua. En octobre 2018, il lance la ligne Vegas del Purial, sous cape Sumatra d''Équateur, sur sous-cape et tripe nicaraguayennes.

En janvier 2018, au festival Puro Sabor, Arturo Fuente annonce une nouvelle fabrique à Estelí, la Gran Fabrica de Tabacos La Bella y La Bestia, et en confie la conduite à Felix Mesa. En 2023, Mesa quitte les opérations nicaraguayennes de Fuente et revient à El Galan, dit Halfwheel.

En septembre 2026, Cigarworld.de vend quatre lignes d''El Galan : la Reserva Especial, sous cape oscuro, corsée ; la Connecticut, puro nicaraguayen de profil doux ; la Maduro, sous cape brésilienne ; et la Tabaco de la Casa, présentée comme l''entrée de gamme. En janvier 2016, Cuenca Cigars présentait aussi une ligne Doña Nieves, en Gran Reserva et Sentimiento.',
        '[{"name":"Reserva Especial","color":"#4A2C1A","force":"Full","wrapper":"Oscuro","vitolas":[],"story":"Cape oscuro, corsée, dit Cigarworld.de."},{"name":"Connecticut","color":"#C9A96E","force":null,"wrapper":"Nicaragua (puro)","vitolas":[],"story":"Puro nicaraguayen, cape, sous-cape et tripe du Nicaragua, de profil doux, dit Cigarworld.de."},{"name":"Maduro","color":"#4A3728","force":null,"wrapper":"Brésil","vitolas":[],"story":"Cape brésilienne, dit Cigarworld.de."},{"name":"Tabaco de la Casa","color":"#A0522D","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Présentée comme l''entrée de gamme, dit Cigarworld.de."}]',
        'Felix A. Mesa''s paternal grandparents, Felipe and Caridad Mesa, grew tobacco in the Cuban province of Las Villas. Mesa founded El Galan Cigars in 2013, naming it after the nickname his grandfather, always elegantly dressed, had carried in Cuba; his cigars are rolled at his own factory, El Galan Cigars S.A., in Estelí, Nicaragua. In October 2018, he launched the Vegas del Purial line, under an Ecuadorian Sumatra wrapper, on a Nicaraguan binder and filler.

In January 2018, at the Puro Sabor festival, Arturo Fuente announced a new factory in Estelí, the Gran Fabrica de Tabacos La Bella y La Bestia, and put Felix Mesa in charge of it. In 2023, Mesa left Fuente''s Nicaraguan operations and returned to El Galan, says Halfwheel.

By September 2026, Cigarworld.de sells four El Galan lines: the Reserva Especial, under an oscuro wrapper, full-bodied; the Connecticut, a Nicaraguan puro with a mild profile; the Maduro, under a Brazilian wrapper; and the Tabaco de la Casa, presented as the entry-level line. In January 2016, Cuenca Cigars also featured a Doña Nieves line, in Gran Reserva and Sentimiento.',
        '[{"name":"Reserva Especial","color":"#4A2C1A","force":"Full","wrapper":"Oscuro","vitolas":[],"story":"Oscuro wrapper, full-bodied, says Cigarworld.de."},{"name":"Connecticut","color":"#C9A96E","force":null,"wrapper":"Nicaragua (puro)","vitolas":[],"story":"Nicaraguan puro, Nicaraguan wrapper, binder and filler, mild profile, says Cigarworld.de."},{"name":"Maduro","color":"#4A3728","force":null,"wrapper":"Brazil","vitolas":[],"story":"Brazilian wrapper, says Cigarworld.de."},{"name":"Tabaco de la Casa","color":"#A0522D","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Presented as the entry-level line, says Cigarworld.de."}]',
        'Los abuelos paternos de Felix A. Mesa, Felipe y Caridad Mesa, cultivaban tabaco en la provincia cubana de Las Villas. Mesa funda El Galan Cigars en 2013 y le da el apodo que llevaba en Cuba su abuelo, siempre vestido con elegancia; sus puros se elaboran en su propia fábrica, El Galan Cigars S.A., en Estelí, Nicaragua. En octubre de 2018 lanza la línea Vegas del Purial, con capa Sumatra de Ecuador, sobre capote y tripa nicaragüenses.

En enero de 2018, en el festival Puro Sabor, Arturo Fuente anuncia una nueva fábrica en Estelí, la Gran Fabrica de Tabacos La Bella y La Bestia, y confía su dirección a Felix Mesa. En 2023, Mesa deja las operaciones nicaragüenses de Fuente y regresa a El Galan, dice Halfwheel.

En septiembre de 2026, Cigarworld.de vende cuatro líneas de El Galan: la Reserva Especial, con capa oscuro, de cuerpo pleno; la Connecticut, puro nicaragüense de perfil suave; la Maduro, con capa brasileña; y la Tabaco de la Casa, presentada como la línea de entrada. En enero de 2016, Cuenca Cigars presentaba también una línea Doña Nieves, en Gran Reserva y Sentimiento.',
        '[{"name":"Reserva Especial","color":"#4A2C1A","force":"Full","wrapper":"Oscuro","vitolas":[],"story":"Capa oscuro, de cuerpo pleno, dice Cigarworld.de."},{"name":"Connecticut","color":"#C9A96E","force":null,"wrapper":"Nicaragua (puro)","vitolas":[],"story":"Puro nicaragüense, capa, capote y tripa de Nicaragua, de perfil suave, dice Cigarworld.de."},{"name":"Maduro","color":"#4A3728","force":null,"wrapper":"Brasil","vitolas":[],"story":"Capa brasileña, dice Cigarworld.de."},{"name":"Tabaco de la Casa","color":"#A0522D","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Presentada como la línea de entrada, dice Cigarworld.de."}]',
        'Die väterlichen Großeltern von Felix A. Mesa, Felipe und Caridad Mesa, bauten Tabak in der kubanischen Provinz Las Villas an. Mesa gründet 2013 El Galan Cigars und gibt der Marke den Spitznamen, den sein stets elegant gekleideter Großvater in Kuba trug; seine Zigarren werden in seiner eigenen Fabrik, El Galan Cigars S.A., in Estelí, Nicaragua, gerollt. Im Oktober 2018 bringt er die Linie Vegas del Purial heraus, mit Sumatra-Deckblatt aus Ecuador auf nicaraguanischem Umblatt und nicaraguanischer Einlage.

Im Januar 2018 kündigt Arturo Fuente beim Festival Puro Sabor eine neue Fabrik in Estelí an, die Gran Fabrica de Tabacos La Bella y La Bestia, und überträgt ihre Leitung Felix Mesa. 2023 verlässt Mesa die nicaraguanischen Aktivitäten von Fuente und kehrt zu El Galan zurück, so Halfwheel.

Im September 2026 verkauft Cigarworld.de vier Linien von El Galan: die Reserva Especial mit Oscuro-Deckblatt, kräftig; die Connecticut, ein nicaraguanischer Puro mit mildem Profil; die Maduro mit brasilianischem Deckblatt; und die Tabaco de la Casa, vorgestellt als Einstiegslinie. Im Januar 2016 stellte Cuenca Cigars zudem eine Linie Doña Nieves vor, in Gran Reserva und Sentimiento.',
        '[{"name":"Reserva Especial","color":"#4A2C1A","force":"Full","wrapper":"Oscuro","vitolas":[],"story":"Oscuro-Deckblatt, kräftig, so Cigarworld.de."},{"name":"Connecticut","color":"#C9A96E","force":null,"wrapper":"Nicaragua (puro)","vitolas":[],"story":"Nicaraguanischer Puro, Deckblatt, Umblatt und Einlage aus Nicaragua, mildes Profil, so Cigarworld.de."},{"name":"Maduro","color":"#4A3728","force":null,"wrapper":"Brasilien","vitolas":[],"story":"Brasilianisches Deckblatt, so Cigarworld.de."},{"name":"Tabaco de la Casa","color":"#A0522D","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Vorgestellt als Einstiegslinie, so Cigarworld.de."}]',
        'Felix A. Mesa的祖父母Felipe与Caridad Mesa曾在古巴拉斯维利亚斯省种植烟草。Mesa于2013年创立El Galan Cigars，并沿用祖父在古巴时的绰号为其命名，祖父当年总是衣着优雅；其雪茄在自家工厂El Galan Cigars S.A.（位于尼加拉瓜埃斯特利）卷制。2018年10月，他推出Vegas del Purial系列，采用厄瓜多尔Sumatra茄衣，搭配尼加拉瓜茄套与茄芯。

2018年1月，在Puro Sabor节上，Arturo Fuente宣布将在埃斯特利新建工厂Gran Fabrica de Tabacos La Bella y La Bestia，并交由Felix Mesa主持。2023年，据Halfwheel报道，Mesa离开Fuente在尼加拉瓜的业务，回归El Galan。

截至2026年9月，Cigarworld.de销售El Galan的四个系列：Reserva Especial，采用oscuro茄衣，浓郁；Connecticut，尼加拉瓜puro，口感柔和；Maduro，采用巴西茄衣；以及Tabaco de la Casa，被称为入门系列。2016年1月，Cuenca Cigars还曾推出Doña Nieves系列，分Gran Reserva与Sentimiento两款。',
        '[{"name":"Reserva Especial","color":"#4A2C1A","force":"Full","wrapper":"Oscuro","vitolas":[],"story":"oscuro茄衣，浓郁，据Cigarworld.de介绍。"},{"name":"Connecticut","color":"#C9A96E","force":null,"wrapper":"尼加拉瓜（puro）","vitolas":[],"story":"尼加拉瓜puro，茄衣、茄套与茄芯均产自尼加拉瓜，口感柔和，据Cigarworld.de介绍。"},{"name":"Maduro","color":"#4A3728","force":null,"wrapper":"巴西","vitolas":[],"story":"巴西茄衣，据Cigarworld.de介绍。"},{"name":"Tabaco de la Casa","color":"#A0522D","force":null,"wrapper":"未公开","vitolas":[],"story":"被列为入门系列，据Cigarworld.de介绍。"}]',
        'أمضى جدّا Felix A. Mesa لأبيه، Felipe وCaridad Mesa، سنوات في زراعة التبغ بمقاطعة لاس بياس الكوبية. أسّس Mesa شركة El Galan Cigars عام 2013، وأطلق عليها اللقب الذي كان يحمله جدّه في كوبا وكان دائم الأناقة في ملبسه؛ وتُلَفّ سيجاراته في مصنعه الخاص El Galan Cigars S.A. في إستيلي بنيكاراغوا. وفي أكتوبر 2018 أطلق خط Vegas del Purial، بغلاف Sumatra إكوادوري على رباط وحشوة نيكاراغويين.

في يناير 2018، وخلال مهرجان Puro Sabor، أعلنت Arturo Fuente عن مصنع جديد في إستيلي هو Gran Fabrica de Tabacos La Bella y La Bestia، وأسندت إدارته إلى Felix Mesa. وفي 2023، ترك Mesa عمليات Fuente في نيكاراغوا وعاد إلى El Galan، بحسب Halfwheel.

بحلول سبتمبر 2026، تبيع Cigarworld.de أربعة خطوط من El Galan: Reserva Especial، بغلاف oscuro، وهي شديدة القوة؛ وConnecticut، وهو puro نيكاراغوي بطابع خفيف؛ وMaduro، بغلاف برازيلي؛ وTabaco de la Casa، التي تُقدَّم بوصفها خط الدخول. وفي يناير 2016، قدّمت Cuenca Cigars أيضًا خط Doña Nieves، بنسختي Gran Reserva وSentimiento.',
        '[{"name":"Reserva Especial","color":"#4A2C1A","force":"Full","wrapper":"Oscuro","vitolas":[],"story":"غلاف oscuro، شديد القوة، بحسب Cigarworld.de."},{"name":"Connecticut","color":"#C9A96E","force":null,"wrapper":"نيكاراغوا (puro)","vitolas":[],"story":"puro نيكاراغوي، غلاف ورباط وحشوة من نيكاراغوا، بطابع خفيف، بحسب Cigarworld.de."},{"name":"Maduro","color":"#4A3728","force":null,"wrapper":"البرازيل","vitolas":[],"story":"غلاف برازيلي، بحسب Cigarworld.de."},{"name":"Tabaco de la Casa","color":"#A0522D","force":null,"wrapper":"غير معلن","vitolas":[],"story":"تُقدَّم بوصفها خط الدخول، بحسب Cigarworld.de."}]')
