INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('German Engineered Cigars',
        'dominican',
        '2016 — Oliver Nickels et associés, Hambourg',
        'Chez Intercigar S.A. (Maurice Koks), Tamboril (Rép. dominicaine), et Tabacalera Tambor (Víctor Calvo), Estelí (Nicaragua)',
        'cigar-coop.com « Cigar News: German Engineered Rauchvergnügen Brand Launches with #42 » (février 2016 : premier cigare de la maison, Rauchvergnügen #42, roulé chez Intercigar S.A., en République dominicaine ; cape équatorienne hybride, sous-cape dominicaine de criollo 98, tripe de piloto cubano dominicain, de tabac nicaraguayen et de tabac américain de Pennsylvanie ; fondateurs Oliver Nickels, Jan-Klaas Mahler et Joachim Sadowski) ; cigar-coop.com « Cigar News: German Engineered Cigars Addresses InterCigar S.A. Fire » (29 septembre 2022 : incendie du 26 septembre 2022 chez Intercigar S.A., propriété de Maurice Koks, qui roule la ligne RVGN Rauchvergnügen de la maison ; Raumzeit vient du Nicaragua) ; cigar-coop.com « Cigar Review: Raumziet Robusto by German Engineered Cigars » (février 2023 : Raumzeit roulée chez Tabacalera Tambor ; cape nicaraguayenne de Connecticut, sous-cape indonésienne de Sumatra, tripe nicaraguayenne de Jalapa et dominicaine de piloto) ; cigardojo.com « German Engineered Raumzeit Robusto » (octobre 2022 : Raumzeit roulée chez Tabacalera Tambor de Estelí S.A., au Nicaragua ; fondateurs Oliver Nickels, Jan-Klaas Mahler et Joachim Sadowski ; marque lancée en 2016 sous le nom Rauchvergnügen, rebaptisée German Engineered Cigars en 2020) ; cigarjournal.com « German Engineered Cigars Announcing Weltschmerz » (date non précisée : cape équatorienne habano oscuro, sous-cape nicaraguayenne de Jalapa, tripe nicaraguayenne d''Estelí et de Jalapa, roulée chez Tabacalera Tambor, au Nicaragua) ; cigarjournal.com « German Engineered Cigars Introduces RVGN Extrem » (2026 : dixième anniversaire de la maison, fondée en mars 2016 ; RVGN Extrem roulée chez Intercigar, en République dominicaine ; cape mexicaine vieillie, sous-cape dominicaine d''olor de Jacagua [variété Carbonel], tripe de piloto cubano et de criollo 98 dominicains [Mao] et nicaraguayens [Condega], profil medium) ; cigarengineers.com (site de la maison, consulté le 25 septembre 2026, dit la maison : fondée en 2016 à Hambourg par Oliver Nickels, informaticien, et Jan Klaas Mahler, graphiste ; RVGN, RVGN Extrem et Kraftwerk roulées en République dominicaine, Raumzeit et Weltschmerz au Nicaragua ; forces : RVGN et RVGN Extrem medium, Raumzeit mild à medium, Weltschmerz medium, Kraftwerk full) ; portal.amelica.org, Revista Científica de FAREM-Estelí (en espagnol, 2020 : usine Tabacalera Tambor de Nicaragua S.A. née en 1996 sous le nom Tabacalera Cachí, à San Ramón, Alajuela [Costa Rica], relocalisée à Estelí fin septembre 2001, rachetée par Víctor Calvo en mai 2002)',
        NULL,
        'German Engineered Cigars naît en 2016 à Hambourg sous le nom de Rauchvergnügen (RVGN) ; ses fondateurs sont Oliver Nickels, informaticien, et Jan Klaas Mahler, graphiste, dit la maison ; Cigar Coop et Cigar Dojo nomment aussi Joachim Sadowski. La marque prend son nom actuel en 2020, dit Cigar Dojo, et fête ses dix ans en 2026.

Le premier cigare, RVGN, est roulé depuis 2016 chez Intercigar S.A., la fabrique de Maurice Koks à Tamboril, en République dominicaine. Raumzeit et Weltschmerz viennent du Nicaragua, de la Tabacalera Tambor, à Estelí : née en 1996 au Costa Rica sous le nom de Tabacalera Cachí, installée à Estelí fin septembre 2001, elle est rachetée par Víctor Calvo en mai 2002, dit une étude de la FAREM-Estelí.

En septembre 2026, le catalogue compte cinq lignes, dit la maison : RVGN et RVGN Extrem, sortie en 2026 pour les dix ans de la maison, roulées chez Intercigar ; Raumzeit et Weltschmerz, roulées chez Tabacalera Tambor ; et Kraftwerk, corsée, roulée en République dominicaine.',
        '[{"name":"RVGN","color":"#A0522D","force":"Medium","wrapper":"Hybride (Équateur)","vitolas":[],"story":"Cape hybride d''Équateur, sous-cape dominicaine de Criollo 98, tripe de Piloto Cubano dominicain, de tabac nicaraguayen et de tabac de Pennsylvanie, dit Cigar Coop en 2016 ; roulée chez Intercigar S.A., à Tamboril."},{"name":"RVGN Extrem","color":"#6B4226","force":"Medium","wrapper":"Mexique (vieillie)","vitolas":[],"story":"Sortie en 2026 pour les dix ans de la maison ; cape mexicaine vieillie, sous-cape dominicaine d''Olor de Jacagua, tripe de Piloto Cubano et de Criollo 98 dominicains et nicaraguayens ; roulée chez Intercigar S.A., à Tamboril."},{"name":"Raumzeit","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut (Nicaragua)","vitolas":[],"story":"Cape Connecticut du Nicaragua, sous-cape de Sumatra d''Indonésie, tripe nicaraguayenne de Jalapa et dominicaine de Piloto ; roulée chez Tabacalera Tambor, à Estelí, dit Cigar Coop."},{"name":"Weltschmerz","color":"#4A2C1A","force":"Medium","wrapper":"Habano oscuro (Équateur)","vitolas":[],"story":"Cape Habano oscuro d''Équateur, sous-cape de Jalapa, tripe d''Estelí et de Jalapa ; roulée chez Tabacalera Tambor, à Estelí."},{"name":"Kraftwerk","color":"#4A2C1A","force":"Full","wrapper":"Non divulguée","vitolas":[],"story":"Roulée en République dominicaine, corsée, dit la maison."}]',
        'German Engineered Cigars was born in 2016 in Hamburg under the name Rauchvergnügen (RVGN); its founders are Oliver Nickels, a computer scientist, and Jan Klaas Mahler, a graphic designer, says the house; Cigar Coop and Cigar Dojo also name Joachim Sadowski. The brand took its current name in 2020, says Cigar Dojo, and celebrates its tenth anniversary in 2026.

The first cigar, RVGN, has been rolled since 2016 at Intercigar S.A., Maurice Koks''s factory in Tamboril, in the Dominican Republic. Raumzeit and Weltschmerz come from Nicaragua, from the Tabacalera Tambor, in Estelí: founded in 1996 in Costa Rica under the name Tabacalera Cachí, relocated to Estelí in late September 2001, it was bought by Víctor Calvo in May 2002, says a study by FAREM-Estelí.

By September 2026, the catalogue includes five lines, says the house: RVGN and RVGN Extrem, released in 2026 for the house''s tenth anniversary, rolled at Intercigar; Raumzeit and Weltschmerz, rolled at Tabacalera Tambor; and Kraftwerk, full-bodied, rolled in the Dominican Republic.',
        '[{"name":"RVGN","color":"#A0522D","force":"Medium","wrapper":"Hybrid (Ecuador)","vitolas":[],"story":"Hybrid Ecuadorian wrapper, Dominican Criollo 98 binder, filler of Dominican Piloto Cubano, Nicaraguan tobacco and Pennsylvania tobacco, said Cigar Coop in 2016; rolled at Intercigar S.A., in Tamboril."},{"name":"RVGN Extrem","color":"#6B4226","force":"Medium","wrapper":"Mexico (aged)","vitolas":[],"story":"Released in 2026 for the house''s tenth anniversary; aged Mexican wrapper, Dominican Olor de Jacagua binder, filler of Dominican and Nicaraguan Piloto Cubano and Criollo 98; rolled at Intercigar S.A., in Tamboril."},{"name":"Raumzeit","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut (Nicaragua)","vitolas":[],"story":"Nicaraguan Connecticut wrapper, Indonesian Sumatra binder, Nicaraguan Jalapa and Dominican Piloto filler; rolled at Tabacalera Tambor, in Estelí, says Cigar Coop."},{"name":"Weltschmerz","color":"#4A2C1A","force":"Medium","wrapper":"Habano oscuro (Ecuador)","vitolas":[],"story":"Ecuadorian Habano oscuro wrapper, Jalapa binder, Estelí and Jalapa filler; rolled at Tabacalera Tambor, in Estelí."},{"name":"Kraftwerk","color":"#4A2C1A","force":"Full","wrapper":"Undisclosed","vitolas":[],"story":"Rolled in the Dominican Republic, full-bodied, says the house."}]',
        'German Engineered Cigars nace en 2016 en Hamburgo bajo el nombre de Rauchvergnügen (RVGN); sus fundadores son Oliver Nickels, informático, y Jan Klaas Mahler, diseñador gráfico, dice la casa; Cigar Coop y Cigar Dojo nombran también a Joachim Sadowski. La marca adopta su nombre actual en 2020, dice Cigar Dojo, y celebra su décimo aniversario en 2026.

El primer puro, RVGN, se elabora desde 2016 en Intercigar S.A., la fábrica de Maurice Koks en Tamboril, República Dominicana. Raumzeit y Weltschmerz proceden de Nicaragua, de la Tabacalera Tambor, en Estelí: nacida en 1996 en Costa Rica bajo el nombre de Tabacalera Cachí, trasladada a Estelí a finales de septiembre de 2001, fue adquirida por Víctor Calvo en mayo de 2002, según un estudio de la FAREM-Estelí.

En septiembre de 2026, el catálogo incluye cinco líneas, dice la casa: RVGN y RVGN Extrem, lanzada en 2026 por el décimo aniversario de la casa, elaboradas en Intercigar; Raumzeit y Weltschmerz, elaboradas en Tabacalera Tambor; y Kraftwerk, de cuerpo pleno, elaborada en República Dominicana.',
        '[{"name":"RVGN","color":"#A0522D","force":"Medium","wrapper":"Híbrida (Ecuador)","vitolas":[],"story":"Capa híbrida de Ecuador, capote dominicano de Criollo 98, tripa de Piloto Cubano dominicano, tabaco nicaragüense y tabaco de Pensilvania, según Cigar Coop en 2016; elaborada en Intercigar S.A., en Tamboril."},{"name":"RVGN Extrem","color":"#6B4226","force":"Medium","wrapper":"México (añejada)","vitolas":[],"story":"Lanzada en 2026 por el décimo aniversario de la casa; capa mexicana añejada, capote dominicano de Olor de Jacagua, tripa de Piloto Cubano y Criollo 98 dominicanos y nicaragüenses; elaborada en Intercigar S.A., en Tamboril."},{"name":"Raumzeit","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut (Nicaragua)","vitolas":[],"story":"Capa Connecticut de Nicaragua, capote de Sumatra de Indonesia, tripa nicaragüense de Jalapa y dominicana de Piloto; elaborada en Tabacalera Tambor, en Estelí, dice Cigar Coop."},{"name":"Weltschmerz","color":"#4A2C1A","force":"Medium","wrapper":"Habano oscuro (Ecuador)","vitolas":[],"story":"Capa Habano oscuro de Ecuador, capote de Jalapa, tripa de Estelí y de Jalapa; elaborada en Tabacalera Tambor, en Estelí."},{"name":"Kraftwerk","color":"#4A2C1A","force":"Full","wrapper":"No divulgada","vitolas":[],"story":"Elaborada en República Dominicana, de cuerpo pleno, dice la casa."}]',
        'German Engineered Cigars entsteht 2016 in Hamburg unter dem Namen Rauchvergnügen (RVGN); Gründer sind Oliver Nickels, Informatiker, und Jan Klaas Mahler, Grafikdesigner, so das Haus; Cigar Coop und Cigar Dojo nennen zudem Joachim Sadowski. Die Marke erhält 2020 ihren heutigen Namen, so Cigar Dojo, und feiert 2026 ihr zehnjähriges Bestehen.

Die erste Zigarre, RVGN, wird seit 2016 bei Intercigar S.A. gerollt, der Fabrik von Maurice Koks in Tamboril, Dominikanische Republik. Raumzeit und Weltschmerz stammen aus Nicaragua, von der Tabacalera Tambor in Estelí: 1996 in Costa Rica unter dem Namen Tabacalera Cachí gegründet, Ende September 2001 nach Estelí verlegt, wird sie im Mai 2002 von Víctor Calvo übernommen, so eine Studie der FAREM-Estelí.

Im September 2026 umfasst das Sortiment fünf Linien, so das Haus: RVGN und RVGN Extrem, die 2026 zum zehnjährigen Bestehen des Hauses erscheint, gerollt bei Intercigar; Raumzeit und Weltschmerz, gerollt bei Tabacalera Tambor; und Kraftwerk, kräftig, gerollt in der Dominikanischen Republik.',
        '[{"name":"RVGN","color":"#A0522D","force":"Medium","wrapper":"Hybrid (Ecuador)","vitolas":[],"story":"Hybrides Deckblatt aus Ecuador, dominikanisches Umblatt aus Criollo 98, Einlage aus dominikanischem Piloto Cubano, nicaraguanischem Tabak und Tabak aus Pennsylvania, so Cigar Coop 2016; gerollt bei Intercigar S.A. in Tamboril."},{"name":"RVGN Extrem","color":"#6B4226","force":"Medium","wrapper":"Mexiko (gereift)","vitolas":[],"story":"2026 zum zehnjährigen Bestehen des Hauses erschienen; gereiftes mexikanisches Deckblatt, dominikanisches Umblatt aus Olor de Jacagua, Einlage aus dominikanischem und nicaraguanischem Piloto Cubano und Criollo 98; gerollt bei Intercigar S.A. in Tamboril."},{"name":"Raumzeit","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut (Nicaragua)","vitolas":[],"story":"Connecticut-Deckblatt aus Nicaragua, Umblatt aus indonesischem Sumatra, Einlage aus nicaraguanischem Jalapa und dominikanischem Piloto; gerollt bei Tabacalera Tambor in Estelí, so Cigar Coop."},{"name":"Weltschmerz","color":"#4A2C1A","force":"Medium","wrapper":"Habano Oscuro (Ecuador)","vitolas":[],"story":"Habano-Oscuro-Deckblatt aus Ecuador, Umblatt aus Jalapa, Einlage aus Estelí und Jalapa; gerollt bei Tabacalera Tambor in Estelí."},{"name":"Kraftwerk","color":"#4A2C1A","force":"Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Gerollt in der Dominikanischen Republik, kräftig, so das Haus."}]',
        'German Engineered Cigars于2016年在汉堡创立，最初名为Rauchvergnügen（RVGN）；品牌方称，创始人是信息技术专业人士Oliver Nickels与平面设计师Jan Klaas Mahler；Cigar Coop与Cigar Dojo还提到了Joachim Sadowski。据Cigar Dojo介绍，品牌于2020年改用现名，并于2026年迎来十周年。

头一款雪茄RVGN自2016年起在Intercigar S.A.卷制，该厂位于多米尼加共和国坦博里尔，为Maurice Koks所有。Raumzeit与Weltschmerz产自尼加拉瓜埃斯特利的Tabacalera Tambor：该厂1996年在哥斯达黎加创立，原名Tabacalera Cachí，2001年9月末迁至埃斯特利，2002年5月被Víctor Calvo收购，据FAREM-Estelí的一项研究介绍。

品牌方称，截至2026年9月，产品目录共有五个系列：RVGN与RVGN Extrem（为品牌十周年于2026年推出），均在Intercigar卷制；Raumzeit与Weltschmerz，在Tabacalera Tambor卷制；以及Kraftwerk，浓郁，产自多米尼加共和国。',
        '[{"name":"RVGN","color":"#A0522D","force":"Medium","wrapper":"混合型（厄瓜多尔）","vitolas":[],"story":"厄瓜多尔混合茄衣，多米尼加Criollo 98茄套，茄芯为多米尼加Piloto Cubano、尼加拉瓜烟叶与宾夕法尼亚烟叶，2016年据Cigar Coop介绍；在Intercigar S.A.（坦博里尔）卷制。"},{"name":"RVGN Extrem","color":"#6B4226","force":"Medium","wrapper":"墨西哥（陈化）","vitolas":[],"story":"为品牌十周年于2026年推出；墨西哥陈化茄衣，多米尼加Olor de Jacagua茄套，茄芯为多米尼加与尼加拉瓜的Piloto Cubano及Criollo 98；在Intercigar S.A.（坦博里尔）卷制。"},{"name":"Raumzeit","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut（尼加拉瓜）","vitolas":[],"story":"尼加拉瓜Connecticut茄衣，印度尼西亚Sumatra茄套，茄芯为产自尼加拉瓜哈拉帕与多米尼加的Piloto；在Tabacalera Tambor（埃斯特利）卷制，据Cigar Coop介绍。"},{"name":"Weltschmerz","color":"#4A2C1A","force":"Medium","wrapper":"Habano oscuro（厄瓜多尔）","vitolas":[],"story":"厄瓜多尔Habano oscuro茄衣，哈拉帕茄套，茄芯产自埃斯特利与哈拉帕；在Tabacalera Tambor（埃斯特利）卷制。"},{"name":"Kraftwerk","color":"#4A2C1A","force":"Full","wrapper":"未公开","vitolas":[],"story":"在多米尼加共和国卷制，浓郁，品牌方称。"}]',
        'وُلدت German Engineered Cigars عام 2016 في هامبورغ تحت اسم Rauchvergnügen (RVGN)؛ وبحسب الدار، فإن مؤسسيها هما Oliver Nickels، أخصائي معلوماتية، وJan Klaas Mahler، مصمم غرافيك؛ وتذكر Cigar Coop وCigar Dojo أيضًا اسم Joachim Sadowski. واتخذت العلامة اسمها الحالي عام 2020، بحسب Cigar Dojo، وتحتفل عام 2026 بمرور عشر سنوات على تأسيسها.

أما أول سيجار، RVGN، فيُلَفّ منذ 2016 في Intercigar S.A.، مصنع Maurice Koks في تامبوريل بجمهورية الدومينيكان. وتأتي Raumzeit وWeltschmerz من نيكاراغوا، من Tabacalera Tambor في إستيلي: تأسست عام 1996 في كوستاريكا باسم Tabacalera Cachí، وانتقلت إلى إستيلي في أواخر سبتمبر 2001، واشتراها Víctor Calvo في مايو 2002، بحسب دراسة لـFAREM-Estelí.

بحلول سبتمبر 2026، يضمّ الكتالوج خمسة خطوط، بحسب الدار: RVGN وRVGN Extrem، الذي صدر عام 2026 بمناسبة مرور عشر سنوات على تأسيس الدار، وكلاهما يُلَفّ في Intercigar؛ وRaumzeit وWeltschmerz، يُلَفّان في Tabacalera Tambor؛ وKraftwerk، شديد القوة، يُلَفّ في جمهورية الدومينيكان.',
        '[{"name":"RVGN","color":"#A0522D","force":"Medium","wrapper":"هجين (الإكوادور)","vitolas":[],"story":"غلاف هجين من الإكوادور، ورباط دومينيكي من Criollo 98، وحشوة من Piloto Cubano دومينيكي وتبغ نيكاراغوي وتبغ من بنسلفانيا، بحسب Cigar Coop عام 2016؛ يُلَفّ في Intercigar S.A. بتامبوريل."},{"name":"RVGN Extrem","color":"#6B4226","force":"Medium","wrapper":"المكسيك (معتَّق)","vitolas":[],"story":"صدر عام 2026 بمناسبة مرور عشر سنوات على تأسيس الدار؛ غلاف مكسيكي معتَّق، ورباط دومينيكي من Olor de Jacagua، وحشوة من Piloto Cubano وCriollo 98 دومينيكيين ونيكاراغويين؛ يُلَفّ في Intercigar S.A. بتامبوريل."},{"name":"Raumzeit","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut (نيكاراغوا)","vitolas":[],"story":"غلاف Connecticut من نيكاراغوا، ورباط Sumatra إندونيسي، وحشوة Piloto من خالابا بنيكاراغوا ومن جمهورية الدومينيكان؛ يُلَفّ في Tabacalera Tambor بإستيلي، بحسب Cigar Coop."},{"name":"Weltschmerz","color":"#4A2C1A","force":"Medium","wrapper":"Habano oscuro (الإكوادور)","vitolas":[],"story":"غلاف Habano oscuro من الإكوادور، ورباط من خالابا، وحشوة من إستيلي وخالابا؛ يُلَفّ في Tabacalera Tambor بإستيلي."},{"name":"Kraftwerk","color":"#4A2C1A","force":"Full","wrapper":"غير معلن","vitolas":[],"story":"يُلَفّ في جمهورية الدومينيكان، وهو شديد القوة، بحسب الدار."}]')
