INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('H.R.',
        'nicaragua',
        '2014 — Hirochi Robaina',
        'Chez La Corona Cigars S.A. (Omar González Alemán), Estelí',
        'cigaraficionado.com « HR From Cubanacan: Robaina In Stores Now » (2014 : Hirochi Robaina, petit-fils d''Alejandro Robaina, avait repris quatre ans plus tôt l''exploitation familiale de Cuchillas de Barbacoa, à Pinar del Río ; HR roulée à Estelí, Nicaragua, sous la direction d''Omar González Alemán ; cape maduro équatorienne de semence Habano 2000, sous-cape et tripe nicaraguayennes de Jalapa et d''Estelí) ; cigaraficionado.com « HR Brand Finds New Distributor » (2016 : Cubanacan n''était que le distributeur américain de HR, roulée par La Corona, fabrique d''Omar Gonzalez Alemán à Estelí ; rupture entre La Corona et Cubanacan en 2015 — roulage interrompu en avril, séparation officialisée en juillet, roulage repris en septembre ; nouveau distributeur, White Hat, de Houston, à partir de février 2016) ; dojoverse.com « HR Black » (consulté le 25 septembre 2026 : HR Black roulée à La Corona Cigars S.A., au Nicaragua, sous la direction du maître rouleur Omar González ; cape habano équatorienne sur sous-cape et tripe nicaraguayennes ; marque passée par de nombreux distributeurs en une décennie) ; houseofgrauer.com « HR Cigars » (1er avril 2024 : Hirochi Robaina, petit-fils d''Alejandro Robaina ; marque lancée fin 2014 ; roulée chez La Corona Cigars S.A., au Nicaragua, par Omar González avec Omar González-Alemán ; White légère et nuancée, Signature de force medium, Blue ample et puissante ; tripe de Jalapa et d''Estelí, sous-cape de Jalapa, cape maduro d''Équateur) ; zigarren.zone « InterTabac 24 exclusive: HR Hirochi Robaina cigars » (2024, en anglais : retour à InterTabac 2024 après une pause liée à la pandémie ; roulage au Nicaragua ; importateur suisse Urs Portmann Tabakwaren AG) ; cigarjournal.com « Hirochi Robaina Introduces Limited Jar and Anniversary Humidor » (septembre 2026 : présentation à InterTabac 2026 d''un tirage limité de bocaux d''HR Signature Belicoso, vingt et un cigares, fabriqués en Chine, vendus sur précommande après le succès de la ligne en Asie, et d''un humidor anniversaire à dix exemplaires marquant dix ans de la maison) ; cigarworld.de « H.R. Signature » (consulté le 25 septembre 2026 : fabrique Tabacalera La Corona Cigars S.A., Omar Gonzalez ; totalmente a mano ; cape colorado foncé d''Équateur, sous-cape et tripe du Nicaragua ; plus corsée que la ligne White)',
        '["HR","Hirochi Robaina"]',
        'Hirochi Robaina, petit-fils du vegero cubain Alejandro Robaina, reprend vers 2010 l''exploitation familiale de Cuchillas de Barbacoa, à Pinar del Río. Fin 2014, il lance hors de Cuba son propre cigare, HR, roulé à la main chez La Corona Cigars S.A., la fabrique d''Omar González Alemán à Estelí, au Nicaragua : cape maduro d''Équateur de semence Habano 2000, sous-cape et tripe nicaraguayennes de Jalapa et d''Estelí.

Aux États-Unis, la marque est d''abord distribuée par Cubanacan. En 2015, La Corona et Cubanacan rompent : le roulage s''interrompt en avril, la séparation est officialisée en juillet et le roulage reprend en septembre ; White Hat, de Houston, distribue la marque à partir de février 2016.

Après une pause liée à la pandémie, dit Zigarren.zone, Hirochi Robaina relance HR à l''InterTabac 2024, toujours roulée chez La Corona, avec une nouvelle ligne, HR Black, aux côtés des White, Signature et Blue ; en Suisse, Urs Portmann Tabakwaren l''importe. En septembre 2026, à l''InterTabac, la maison présente un tirage limité de bocaux de vingt et un HR Signature Belicoso, vendus sur précommande, et un humidor à dix exemplaires.',
        '[{"name":"HR White","color":"#C9A96E","force":"Mild","wrapper":"Non divulguée","vitolas":[],"story":"Ligne du lancement de 2014, légère et nuancée, dit House of Grauer."},{"name":"HR Signature","color":"#A0522D","force":"Medium","wrapper":"Colorado (Équateur)","vitolas":[],"story":"Ligne du lancement de 2014, de force medium, dit House of Grauer ; cape colorado foncé d''Équateur, sous-cape et tripe du Nicaragua, roulée totalement à la main chez La Corona, dit Cigarworld.de."},{"name":"HR Blue","color":"#4A3728","force":"Full","wrapper":"Non divulguée","vitolas":[],"story":"Ligne du lancement de 2014, ample et puissante, dit House of Grauer."},{"name":"HR Black","color":"#6B4226","force":null,"wrapper":"Habano (Équateur)","vitolas":[],"story":"Ajoutée au retour de 2024 ; cape Habano d''Équateur sur sous-cape et tripe du Nicaragua, roulée chez La Corona, dit Dojoverse."}]',
        'Hirochi Robaina, grandson of the Cuban vegero Alejandro Robaina, took over the family estate of Cuchillas de Barbacoa, in Pinar del Río, around 2010. In late 2014, he launched his own cigar outside Cuba, HR, hand-rolled at La Corona Cigars S.A., Omar González Alemán''s factory in Estelí, Nicaragua: maduro wrapper from Ecuador of Habano 2000 seed, Nicaraguan binder and filler from Jalapa and Estelí.

In the United States, the brand was first distributed by Cubanacan. In 2015, La Corona and Cubanacan split: rolling stopped in April, the separation was made official in July and rolling resumed in September; White Hat, of Houston, has distributed the brand since February 2016.

After a pause linked to the pandemic, says Zigarren.zone, Hirochi Robaina relaunched HR at InterTabac 2024, still hand-rolled at La Corona, with a new line, HR Black, alongside the White, Signature and Blue; in Switzerland, Urs Portmann Tabakwaren imports it. In September 2026, at InterTabac, the house presented a limited run of jars of twenty-one HR Signature Belicoso, sold by pre-order, and a ten-piece humidor.',
        '[{"name":"HR White","color":"#C9A96E","force":"Mild","wrapper":"Undisclosed","vitolas":[],"story":"Line from the 2014 launch, light and nuanced, says House of Grauer."},{"name":"HR Signature","color":"#A0522D","force":"Medium","wrapper":"Colorado (Ecuador)","vitolas":[],"story":"Line from the 2014 launch, medium-bodied, says House of Grauer; dark colorado wrapper from Ecuador, Nicaraguan binder and filler, entirely hand-rolled at La Corona, says Cigarworld.de."},{"name":"HR Blue","color":"#4A3728","force":"Full","wrapper":"Undisclosed","vitolas":[],"story":"Line from the 2014 launch, full and powerful, says House of Grauer."},{"name":"HR Black","color":"#6B4226","force":null,"wrapper":"Habano (Ecuador)","vitolas":[],"story":"Added with the 2024 return; Ecuadorian Habano wrapper on Nicaraguan binder and filler, rolled at La Corona, says Dojoverse."}]',
        'Hirochi Robaina, nieto del vegero cubano Alejandro Robaina, retoma hacia 2010 la explotación familiar de Cuchillas de Barbacoa, en Pinar del Río. A finales de 2014 lanza, fuera de Cuba, su propio puro, HR, elaborado a mano en La Corona Cigars S.A., la fábrica de Omar González Alemán en Estelí, Nicaragua: capa maduro de Ecuador de semilla Habano 2000, capote y tripa nicaragüenses de Jalapa y de Estelí.

En Estados Unidos, la marca es distribuida primero por Cubanacan. En 2015, La Corona y Cubanacan rompen relaciones: la elaboración se interrumpe en abril, la separación se oficializa en julio y la elaboración se reanuda en septiembre; White Hat, de Houston, distribuye la marca desde febrero de 2016.

Tras una pausa vinculada a la pandemia, dice Zigarren.zone, Hirochi Robaina relanza HR en InterTabac 2024, elaborada siempre en La Corona, con una nueva línea, HR Black, junto a las White, Signature y Blue; en Suiza la importa Urs Portmann Tabakwaren. En septiembre de 2026, en InterTabac, la casa presenta una tirada limitada de tarros de veintiún HR Signature Belicoso, vendidos por encargo, y un humidor de diez unidades.',
        '[{"name":"HR White","color":"#C9A96E","force":"Mild","wrapper":"No divulgada","vitolas":[],"story":"Línea del lanzamiento de 2014, ligera y matizada, dice House of Grauer."},{"name":"HR Signature","color":"#A0522D","force":"Medium","wrapper":"Colorado (Ecuador)","vitolas":[],"story":"Línea del lanzamiento de 2014, de fuerza medium, dice House of Grauer; capa colorado oscuro de Ecuador, capote y tripa de Nicaragua, elaborada totalmente a mano en La Corona, dice Cigarworld.de."},{"name":"HR Blue","color":"#4A3728","force":"Full","wrapper":"No divulgada","vitolas":[],"story":"Línea del lanzamiento de 2014, amplia y potente, dice House of Grauer."},{"name":"HR Black","color":"#6B4226","force":null,"wrapper":"Habano (Ecuador)","vitolas":[],"story":"Añadida en el regreso de 2024; capa Habano de Ecuador sobre capote y tripa de Nicaragua, elaborada en La Corona, dice Dojoverse."}]',
        'Hirochi Robaina, Enkel des kubanischen Vegero Alejandro Robaina, übernimmt um 2010 den Familienbetrieb Cuchillas de Barbacoa in Pinar del Río. Ende 2014 bringt er außerhalb Kubas seine eigene Zigarre heraus, HR, von Hand gerollt bei La Corona Cigars S.A., der Fabrik von Omar González Alemán in Estelí, Nicaragua: Maduro-Deckblatt aus Ecuador der Sorte Habano 2000, nicaraguanisches Umblatt und nicaraguanische Einlage aus Jalapa und Estelí.

In den USA wird die Marke zunächst von Cubanacan vertrieben. 2015 trennen sich La Corona und Cubanacan: Das Rollen wird im April unterbrochen, die Trennung im Juli offiziell besiegelt und das Rollen im September wieder aufgenommen; White Hat aus Houston vertreibt die Marke seit Februar 2016.

Nach einer pandemiebedingten Pause, so Zigarren.zone, bringt Hirochi Robaina HR 2024 auf der InterTabac neu heraus, weiterhin bei La Corona von Hand gerollt, mit einer neuen Linie, HR Black, neben White, Signature und Blue; in der Schweiz importiert sie Urs Portmann Tabakwaren. Im September 2026 stellt das Haus auf der InterTabac eine limitierte Auflage von Gläsern mit einundzwanzig HR Signature Belicoso vor, die auf Vorbestellung verkauft werden, sowie einen Humidor in zehn Exemplaren.',
        '[{"name":"HR White","color":"#C9A96E","force":"Mild","wrapper":"Nicht angegeben","vitolas":[],"story":"Linie aus dem Start 2014, leicht und nuanciert, so House of Grauer."},{"name":"HR Signature","color":"#A0522D","force":"Medium","wrapper":"Colorado (Ecuador)","vitolas":[],"story":"Linie aus dem Start 2014, Stärke medium, so House of Grauer; dunkles Colorado-Deckblatt aus Ecuador, Umblatt und Einlage aus Nicaragua, vollständig von Hand gerollt bei La Corona, so Cigarworld.de."},{"name":"HR Blue","color":"#4A3728","force":"Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Linie aus dem Start 2014, voll und kraftvoll, so House of Grauer."},{"name":"HR Black","color":"#6B4226","force":null,"wrapper":"Habano (Ecuador)","vitolas":[],"story":"Mit der Rückkehr 2024 hinzugefügt; Habano-Deckblatt aus Ecuador auf nicaraguanischem Umblatt und nicaraguanischer Einlage, gerollt bei La Corona, so Dojoverse."}]',
        'Hirochi Robaina是古巴vegero Alejandro Robaina之孙，约在2010年接手位于比那尔德里奥的家族产业Cuchillas de Barbacoa。2014年底，他在古巴以外推出了自己的雪茄HR，由Omar González Alemán位于尼加拉瓜埃斯特利的工厂La Corona Cigars S.A.手工卷制：采用Habano 2000品种的厄瓜多尔maduro茄衣，茄套与茄芯为尼加拉瓜哈拉帕与埃斯特利产。

在美国，该品牌最初由Cubanacan经销。2015年，La Corona与Cubanacan决裂：卷制工作于4月中断，双方于7月正式分手，卷制于9月恢复；来自休斯顿的White Hat自2016年2月起经销该品牌。

据Zigarren.zone报道，经过与疫情相关的停顿后，Hirochi Robaina于2024年InterTabac展会上重启HR，仍在La Corona卷制，并推出新系列HR Black，与White、Signature、Blue并列；在瑞士，由Urs Portmann Tabakwaren负责进口。2026年9月，在InterTabac上，品牌方展示了限量罐装HR Signature Belicoso，共二十一支，可预订购买，以及一款限量十件的雪茄保湿盒。',
        '[{"name":"HR White","color":"#C9A96E","force":"Mild","wrapper":"未公开","vitolas":[],"story":"2014年首发系列之一，轻柔而富有层次，据House of Grauer介绍。"},{"name":"HR Signature","color":"#A0522D","force":"Medium","wrapper":"Colorado（厄瓜多尔）","vitolas":[],"story":"2014年首发系列之一，力道为medium，据House of Grauer介绍；厄瓜多尔深色colorado茄衣，尼加拉瓜茄套与茄芯，在La Corona完全手工卷制，据Cigarworld.de介绍。"},{"name":"HR Blue","color":"#4A3728","force":"Full","wrapper":"未公开","vitolas":[],"story":"2014年首发系列之一，饱满而有力，据House of Grauer介绍。"},{"name":"HR Black","color":"#6B4226","force":null,"wrapper":"Habano（厄瓜多尔）","vitolas":[],"story":"随2024年回归新增；厄瓜多尔Habano茄衣搭配尼加拉瓜茄套与茄芯，在La Corona卷制，据Dojoverse介绍。"}]',
        'يتولى Hirochi Robaina، حفيد الـvegero الكوبي Alejandro Robaina، حوالي عام 2010 إدارة المزرعة العائلية Cuchillas de Barbacoa في بينار ديل ريو. وفي أواخر 2014، يطلق خارج كوبا سيجاره الخاص HR، الملفوف يدويًا في La Corona Cigars S.A.، مصنع Omar González Alemán في إستيلي بنيكاراغوا: غلاف maduro من الإكوادور من صنف Habano 2000، ورباط وحشوة نيكاراغويان من خالابا وإستيلي.

في الولايات المتحدة، وزّعت Cubanacan العلامة في البداية. وفي 2015، انفصلت La Corona عن Cubanacan: توقّف اللف في أبريل، وأصبح الانفصال رسميًا في يوليو، واستؤنف اللف في سبتمبر؛ وتتولى White Hat من هيوستن توزيع العلامة منذ فبراير 2016.

بعد توقف مرتبط بالجائحة، بحسب Zigarren.zone، أعاد Hirochi Robaina إطلاق HR في معرض InterTabac 2024، وهي لا تزال تُلَفّ في La Corona، مع خط جديد هو HR Black، إلى جانب White وSignature وBlue؛ وفي سويسرا تستوردها Urs Portmann Tabakwaren. وفي سبتمبر 2026، وخلال InterTabac، قدّمت الدار إصدارًا محدودًا من برطمانات تضمّ واحدًا وعشرين سيجارًا من HR Signature Belicoso، تُباع بالطلب المسبق، وهيوميدور من عشر قطع.',
        '[{"name":"HR White","color":"#C9A96E","force":"Mild","wrapper":"غير معلن","vitolas":[],"story":"من خطوط الإطلاق عام 2014، خفيفة ومتعددة النكهات، بحسب House of Grauer."},{"name":"HR Signature","color":"#A0522D","force":"Medium","wrapper":"Colorado (الإكوادور)","vitolas":[],"story":"من خطوط الإطلاق عام 2014، بقوة medium، بحسب House of Grauer؛ غلاف colorado داكن من الإكوادور، ورباط وحشوة من نيكاراغوا، ملفوفة يدويًا بالكامل في La Corona، بحسب Cigarworld.de."},{"name":"HR Blue","color":"#4A3728","force":"Full","wrapper":"غير معلن","vitolas":[],"story":"من خطوط الإطلاق عام 2014، ممتلئة القوام وقوية المذاق، بحسب House of Grauer."},{"name":"HR Black","color":"#6B4226","force":null,"wrapper":"Habano (الإكوادور)","vitolas":[],"story":"أُضيفت مع عودة 2024؛ غلاف Habano من الإكوادور فوق رباط وحشوة من نيكاراغوا، تُلَفّ في La Corona، بحسب Dojoverse."}]')
