-- ── Helvada ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Helvada',
        'nicaragua',
        '2018 — Schwizer Trade, Kallern (Suisse)',
        'Nicaragua — la maison ne nomme pas sa fabrique',
        'schwizertrade.ch « Helvada 51 » (consulté le 25 septembre 2026, dit la maison : format Gran Robusto, force 4 sur 10 ; mélange mis au point par Daniel Schwizer avec Kurt Brandt, de Flor Real Cigars ; cape Habano Maduro Natural d''Équateur, sous-cape de Jalapa [Nicaragua], tripe de Condega [Nicaragua] et de ligero dominicain ; bague Hecho a Mano, que la maison lit comme une tripe façonnée à la machine sous une cape roulée à la main) ; schwizertrade.ch « Über uns » (consulté le 25 septembre 2026, dit la maison : Schwizer Trade GmbH fondée en 2015 par Daniel Schwizer et Andrea Moor) ; daniel-schwizer.ch « Helvada » (consulté le 25 septembre 2026, dit la maison : lancement le 23 mai 2018, mélange mis au point à distance avec Kurt Brandt, qui travaille au Nicaragua) ; zigarren-online.ch « Helvada Zigarren » (consulté le 25 septembre 2026 : deux lignes au catalogue, Helvada et Helvada Dark Line, classées au Nicaragua) ; fumar.ch « Helvada Zigarren » (consulté le 25 septembre 2026 : cinq vitolas — 51 Robusto, 70 Gordo, 02 Salomones, 04 Salomones Oscuro, 91 Gigante — toutes en longfiller, force 3/5) ; cigarworld.de « Helvada Medio Filler Medio Tiempo » (consulté le 25 septembre 2026 : vitola vendue entièrement roulée à la main, cape indonésienne, sous-cape et tripe nicaraguayennes, tabac de medio tiempo)',
        NULL,
        'Daniel Schwizer et Andrea Moor fondent Schwizer Trade GmbH en 2015, à Kallern, en Argovie (Suisse). Le 23 mai 2018, ils lancent leur propre marque, Helvada, dont Daniel Schwizer a mis au point le mélange avec Kurt Brandt, de Flor Real Cigars, qui travaille au Nicaragua, dit la maison.

La maison ne nomme pas sa fabrique. Son 51, au format Gran Robusto, porte une cape Habano maduro d''Équateur sur une sous-cape de Jalapa et une tripe de Condega, au Nicaragua, et de ligero dominicain ; sa bague dit Hecho a mano, ce que la maison lit comme une tripe façonnée à la machine sous une cape roulée à la main. Cigarworld.de vend la Medio Filler Medio Tiempo comme entièrement roulée à la main, sous cape indonésienne, sur sous-cape et tripe nicaraguayennes.

En septembre 2026, le catalogue compte la ligne Helvada, en 51, 70 Gordo, 02 Salomones, 04 Salomones Oscuro et 91 Gigante, dit Fumar.ch, la Dark Line, dit Zigarren-online.ch, et la Medio Filler Medio Tiempo, à base de medio tiempo, les feuilles du sommet du plant.',
        '[{"name":"Helvada","color":"#A0522D","force":"Mild","wrapper":"Non divulguée","vitolas":[],"story":"Le 51, au format Gran Robusto : cape Habano maduro d''Équateur, sous-cape de Jalapa, tripe de Condega et de ligero dominicain, dit la maison ; aussi en 70 Gordo, 02 Salomones, 04 Salomones Oscuro et 91 Gigante, dit Fumar.ch."},{"name":"Helvada Dark Line","color":"#4A3728","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Ligne du catalogue, dit Zigarren-online.ch."},{"name":"Medio Filler Medio Tiempo","color":"#6B4226","force":null,"wrapper":"Indonésie","vitolas":[],"story":"Cape indonésienne, sous-cape et tripe nicaraguayennes de medio tiempo, les feuilles du sommet du plant ; entièrement roulée à la main, dit Cigarworld.de."}]',
        'Daniel Schwizer and Andrea Moor founded Schwizer Trade GmbH in 2015, in Kallern, in the canton of Aargau (Switzerland). On 23 May 2018, they launched their own brand, Helvada, whose blend Daniel Schwizer developed with Kurt Brandt, of Flor Real Cigars, who works in Nicaragua, says the house.

The house does not name its factory. Its 51, in the Gran Robusto format, carries a Habano maduro wrapper from Ecuador over a Jalapa binder and a Condega filler, in Nicaragua, and Dominican ligero; its band reads Hecho a mano, which the house reads as a filler machine-shaped under a hand-rolled wrapper. Cigarworld.de sells the Medio Filler Medio Tiempo as entirely hand-rolled, under an Indonesian wrapper, on Nicaraguan binder and filler.

By September 2026, the catalogue includes the Helvada line, in 51, 70 Gordo, 02 Salomones, 04 Salomones Oscuro and 91 Gigante, says Fumar.ch, the Dark Line, says Zigarren-online.ch, and the Medio Filler Medio Tiempo, based on medio tiempo, the leaves from the top of the plant.',
        '[{"name":"Helvada","color":"#A0522D","force":"Mild","wrapper":"Undisclosed","vitolas":[],"story":"The 51, in the Gran Robusto format: Habano maduro wrapper from Ecuador, Jalapa binder, Condega and Dominican ligero filler, says the house; also in 70 Gordo, 02 Salomones, 04 Salomones Oscuro and 91 Gigante, says Fumar.ch."},{"name":"Helvada Dark Line","color":"#4A3728","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Line in the catalogue, says Zigarren-online.ch."},{"name":"Medio Filler Medio Tiempo","color":"#6B4226","force":null,"wrapper":"Indonesia","vitolas":[],"story":"Indonesian wrapper, Nicaraguan binder and filler of medio tiempo, the leaves from the top of the plant; entirely hand-rolled, says Cigarworld.de."}]',
        'Daniel Schwizer y Andrea Moor fundan Schwizer Trade GmbH en 2015, en Kallern, en el cantón de Argovia (Suiza). El 23 de mayo de 2018 lanzan su propia marca, Helvada, cuya mezcla puso a punto Daniel Schwizer junto con Kurt Brandt, de Flor Real Cigars, que trabaja en Nicaragua, dice la casa.

La casa no nombra su fábrica. Su 51, en formato Gran Robusto, lleva una capa Habano maduro de Ecuador sobre un capote de Jalapa y una tripa de Condega, en Nicaragua, y de ligero dominicano; su anilla dice Hecho a mano, lo que la casa interpreta como una tripa formada a máquina bajo una capa elaborada a mano. Cigarworld.de vende la Medio Filler Medio Tiempo como elaborada totalmente a mano, con capa indonesia, sobre capote y tripa nicaragüenses.

En septiembre de 2026, el catálogo incluye la línea Helvada, en 51, 70 Gordo, 02 Salomones, 04 Salomones Oscuro y 91 Gigante, dice Fumar.ch, la Dark Line, dice Zigarren-online.ch, y la Medio Filler Medio Tiempo, a base de medio tiempo, las hojas de la punta de la planta.',
        '[{"name":"Helvada","color":"#A0522D","force":"Mild","wrapper":"No divulgada","vitolas":[],"story":"El 51, en formato Gran Robusto: capa Habano maduro de Ecuador, capote de Jalapa, tripa de Condega y de ligero dominicano, dice la casa; también en 70 Gordo, 02 Salomones, 04 Salomones Oscuro y 91 Gigante, dice Fumar.ch."},{"name":"Helvada Dark Line","color":"#4A3728","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Línea del catálogo, dice Zigarren-online.ch."},{"name":"Medio Filler Medio Tiempo","color":"#6B4226","force":null,"wrapper":"Indonesia","vitolas":[],"story":"Capa indonesia, capote y tripa nicaragüenses de medio tiempo, las hojas de la punta de la planta; elaborada totalmente a mano, dice Cigarworld.de."}]',
        'Daniel Schwizer und Andrea Moor gründen Schwizer Trade GmbH 2015 in Kallern, im Kanton Aargau (Schweiz). Am 23. Mai 2018 bringen sie ihre eigene Marke heraus, Helvada, deren Mischung Daniel Schwizer gemeinsam mit Kurt Brandt von Flor Real Cigars entwickelt hat, der in Nicaragua arbeitet, so das Haus.

Das Haus nennt seine Fabrik nicht. Ihre 51, im Format Gran Robusto, trägt ein Habano-Maduro-Deckblatt aus Ecuador über einem Umblatt aus Jalapa und einer Einlage aus Condega, Nicaragua, und dominikanischem Ligero; ihre Bauchbinde trägt die Aufschrift Hecho a mano, was das Haus als eine maschinell geformte Einlage unter einem von Hand gerollten Deckblatt liest. Cigarworld.de verkauft die Medio Filler Medio Tiempo als vollständig von Hand gerollt, mit indonesischem Deckblatt, auf nicaraguanischem Umblatt und nicaraguanischer Einlage.

Im September 2026 umfasst das Sortiment die Linie Helvada, in 51, 70 Gordo, 02 Salomones, 04 Salomones Oscuro und 91 Gigante, so Fumar.ch, die Dark Line, so Zigarren-online.ch, sowie die Medio Filler Medio Tiempo auf Basis von Medio Tiempo, den Blättern von der Spitze der Pflanze.',
        '[{"name":"Helvada","color":"#A0522D","force":"Mild","wrapper":"Nicht angegeben","vitolas":[],"story":"Die 51, im Format Gran Robusto: Habano-Maduro-Deckblatt aus Ecuador, Umblatt aus Jalapa, Einlage aus Condega und dominikanischem Ligero, so das Haus; auch in 70 Gordo, 02 Salomones, 04 Salomones Oscuro und 91 Gigante, so Fumar.ch."},{"name":"Helvada Dark Line","color":"#4A3728","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Linie im Sortiment, so Zigarren-online.ch."},{"name":"Medio Filler Medio Tiempo","color":"#6B4226","force":null,"wrapper":"Indonesien","vitolas":[],"story":"Indonesisches Deckblatt, nicaraguanisches Umblatt und Einlage aus Medio Tiempo, den Blättern von der Spitze der Pflanze; vollständig von Hand gerollt, so Cigarworld.de."}]',
        'Daniel Schwizer与Andrea Moor于2015年在瑞士阿尔高州卡勒恩创立Schwizer Trade GmbH。2018年5月23日，两人推出自有品牌Helvada；据品牌介绍，其配方由Daniel Schwizer与在尼加拉瓜工作的Kurt Brandt（Flor Real Cigars）共同研发。

品牌并未公开其工厂名称。其51号雪茄为Gran Robusto规格，茄衣为厄瓜多尔Habano maduro，茄套产自哈拉帕，茄芯由尼加拉瓜孔德加与多米尼加的ligero构成；其雪茄环上印有Hecho a mano字样，品牌将其解读为：茄芯以机器成型，外覆手工卷制的茄衣。Cigarworld.de将Medio Filler Medio Tiempo列为完全手工卷制，采用印度尼西亚茄衣，搭配尼加拉瓜茄套与茄芯。

截至2026年9月，产品目录包括Helvada系列（分51、70 Gordo、02 Salomones、04 Salomones Oscuro与91 Gigante），据Fumar.ch介绍；Dark Line，据Zigarren-online.ch介绍；以及以medio tiempo（植株顶部叶片）为基础的Medio Filler Medio Tiempo。',
        '[{"name":"Helvada","color":"#A0522D","force":"Mild","wrapper":"未公开","vitolas":[],"story":"51号：Gran Robusto规格，厄瓜多尔Habano maduro茄衣，哈拉帕茄套，孔德加与多米尼加ligero茄芯，品牌方称；另有70 Gordo、02 Salomones、04 Salomones Oscuro与91 Gigante规格，据Fumar.ch介绍。"},{"name":"Helvada Dark Line","color":"#4A3728","force":null,"wrapper":"未公开","vitolas":[],"story":"产品目录中的系列，据Zigarren-online.ch介绍。"},{"name":"Medio Filler Medio Tiempo","color":"#6B4226","force":null,"wrapper":"印度尼西亚","vitolas":[],"story":"印度尼西亚茄衣，尼加拉瓜茄套与茄芯，采用medio tiempo（植株顶部叶片）；完全手工卷制，据Cigarworld.de介绍。"}]',
        'أسّس Daniel Schwizer وAndrea Moor شركة Schwizer Trade GmbH عام 2015 في كالرن بكانتون أرغاو (سويسرا). وفي 23 مايو 2018، أطلقا علامتهما الخاصة Helvada، التي وضع Daniel Schwizer مزيجها بالتعاون مع Kurt Brandt من Flor Real Cigars، العامل في نيكاراغوا، بحسب الدار.

لا تُسمّي الدار مصنعها. أما سيجارها 51، بمقاس Gran Robusto، فيحمل غلاف Habano maduro من الإكوادور فوق رباط من خالابا وحشوة من كونديغا بنيكاراغوا وligero دومينيكي؛ وتحمل حلقته عبارة Hecho a mano، التي تقرؤها الدار على أنها حشوة مُشكَّلة آليًا تحت غلاف ملفوف يدويًا. وتبيع Cigarworld.de سيجار Medio Filler Medio Tiempo باعتباره ملفوفًا يدويًا بالكامل، بغلاف إندونيسي، فوق رباط وحشوة نيكاراغويين.

بحلول سبتمبر 2026، يضمّ الكتالوج خط Helvada بمقاسات 51، و70 Gordo، و02 Salomones، و04 Salomones Oscuro، و91 Gigante، بحسب Fumar.ch، وDark Line، بحسب Zigarren-online.ch، وMedio Filler Medio Tiempo، القائم على medio tiempo، أي أوراق قمة النبتة.',
        '[{"name":"Helvada","color":"#A0522D","force":"Mild","wrapper":"غير معلن","vitolas":[],"story":"51، بمقاس Gran Robusto: غلاف Habano maduro من الإكوادور، ورباط من خالابا، وحشوة من كونديغا وligero دومينيكي، بحسب الدار؛ ومتوفر أيضًا بمقاسات 70 Gordo، و02 Salomones، و04 Salomones Oscuro، و91 Gigante، بحسب Fumar.ch."},{"name":"Helvada Dark Line","color":"#4A3728","force":null,"wrapper":"غير معلن","vitolas":[],"story":"خط ضمن الكتالوج، بحسب Zigarren-online.ch."},{"name":"Medio Filler Medio Tiempo","color":"#6B4226","force":null,"wrapper":"إندونيسيا","vitolas":[],"story":"غلاف إندونيسي، ورباط وحشوة نيكاراغويان من medio tiempo، أي أوراق قمة النبتة؛ ملفوفة يدويًا بالكامل، بحسب Cigarworld.de."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Dalay ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Dalay',
        'dominican',
        'Non précisée — Salih Dalay, Sarrebruck',
        'Tabacalera Zauberberg, Santiago de los Caballeros — usine propre, dit la maison ; ligne Nicaragua chez Luciano Cigars, Estelí',
        'dalayzigarren.de « Dalay » (consulté le 25 septembre 2026 : dit que les cigares Dalay sont fabriqués dans sa manufacture propre Zauberberg, en République dominicaine, et liste les lignes Hell, Dunkel, Honduras Hell, Honduras Dunkel, Istanbul, Oase, Sevilla et Limitada) ; dalayzigarren.de « Eigenmarken » (consulté le 25 septembre 2026 : confirme ces lignes et cite Zauberberg, la Tabacalera Altagracia et Luciano Cigars comme manufactures partenaires) ; dalayzigarren.de « Team » (consulté le 25 septembre 2026 : situe la fondation de la maison à plus de vingt-cinq ans, sans date précise ni biographie de Salih Dalay) ; blog.dalayzigarren.de « Dalay Istanbul – Ein Herzensprojekt mit Kunstwert » (en allemand ; consulté le 25 septembre 2026 : Istanbul, ville natale de Salih Dalay ; bague peinte par le micropeintre stambouliote Hasan Kale ; projet d''une dizaine d''années, cigares disponibles le 8 juillet 2023 ; boîtes faites à la manufacture Zauberberg) ; cigarworld.de « Dalay » (consulté le 25 septembre 2026 : décrit les lignes République dominicaine claire et foncée, Honduras claire et foncée sur tabac Corojo, Istanbul, Nicaragua, Sevilla et Oase) ; cigarworld.de « Dalay Istanbul Robusto » (consulté le 25 septembre 2026 : cape Corojo 99 d''Équateur, sous-cape de Pennsylvanie, tripe mêlant tabac turc, dominicain et du Kentucky ; date la fondation de la Tabacalera Zauberberg par Salih Dalay à 2017) ; cigarworld.de « Ferruh Karakasli » (biographie ; consulté le 25 septembre 2026 : Ferruh Karakaşlı né en 1967 à Istanbul, tailleur, collaboration avec Salih Dalay) ; cigarworld.de « Ferruh Karakasli » (fiche produit 90015032 ; consulté le 25 septembre 2026 : fabrique Tabacalera Zauberberg, cape San Andrés du Mexique, sous-cape de Sumatra indonésienne, tripe nicaraguayenne et brésilienne) ; cigar-coop.com « Cigar News: Luciano Cigars and Dalay Zigarren Announce Partnership and Two New Cigars » (consulté le 25 septembre 2026 : accord vieux de cinq ans entre les deux maisons, Dalay Nicaragua assemblée par Luciano Meirelles à l''usine Luciano Cigars d''Estelí, ligne Istanbul en dix ans de préparation et roulée à Zauberberg) ; smokersplanet.de « ''Dalay Oase'', eine Cigarrenoase mit viel Kultur » (en allemand ; consulté le 25 septembre 2026 : fabrique Zauberberg, cape équatorienne foncée, sous-cape et tripe dominicaines, lancement le 15 mai 2026 à Sarrebruck ; histoires de Nasreddin Hodja que Salih Dalay écoutait enfant) ; halfwheel.com « Dalay Oase Launching in Germany This Month » (décrit Zauberberg comme une coentreprise avec des partenaires dominicains, en relation avec Dalay depuis près de trois décennies) ; halfwheel.com « Luciano Cigars and Dalay Zigarren Announce Distribution Agreement, Will Release Istanbul and Dalay Nicaragua at PCA 2023 » (accord de distribution annoncé en 2023, Dalay Nicaragua manufacturée à l''usine Luciano Cigars d''Estelí)',
        NULL,
        'Salih Dalay, né à Istanbul, fonde à Sarrebruck Dalay Zigarren ; la maison dit avoir plus de vingt-cinq ans en 2026. Ses lignes propres sont roulées à la Tabacalera Zauberberg, à Santiago de los Caballeros, en République dominicaine, que la maison dit sa manufacture ; Halfwheel décrit Zauberberg comme une coentreprise avec des partenaires dominicains, liés à Dalay depuis près de trois décennies, et Cigarworld.de en date la fondation par Salih Dalay de 2017.

En septembre 2026, le catalogue compte une version claire et une version foncée roulées en République dominicaine, Hell et Dunkel ; une déclinaison Honduras, elle aussi claire ou foncée, sur des tabacs Corojo ; la ligne Istanbul, sortie le 8 juillet 2023, à tripe de tabac turc, dont la bague porte une miniature du micropeintre stambouliote Hasan Kale, en hommage à la ville natale de Salih Dalay, dit la maison ; la ligne Oase, lancée le 15 mai 2026 à Sarrebruck, inspirée des histoires de Nasreddin Hodja que Salih Dalay écoutait enfant, dit Smokersplanet.de ; et Ferruh Karakasli, avec le couturier turc Ferruh Karakaşlı, né en 1967 à Istanbul, dit Cigarworld.de.

Depuis 2023, la ligne Dalay Nicaragua est roulée par Luciano Meirelles à l''usine Luciano Cigars, à Estelí ; Dalay importe aussi Luciano Cigars en Allemagne, disent Cigar Coop et Halfwheel.',
        '[{"name":"Dalay Hell","color":"#C9A96E","force":"Mild","wrapper":"Non divulguée","vitolas":[],"story":"Version claire du catalogue dominicain, à l''aromatique épicée, dit Cigarworld.de."},{"name":"Dalay Dunkel","color":"#4A3728","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Version foncée, aux notes de chocolat et d''épices, dit Cigarworld.de."},{"name":"Dalay Honduras Hell","color":"#A0522D","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Version claire sur tabac Corojo hondurien, dit Cigarworld.de."},{"name":"Dalay Honduras Dunkel","color":"#6B4226","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Version foncée sur tabac Corojo hondurien, aux notes sucrées et chocolatées, dit Cigarworld.de."},{"name":"Dalay Istanbul","color":"#A0522D","force":null,"wrapper":"Corojo 99 (Équateur)","vitolas":[],"story":"Sortie le 8 juillet 2023, en hommage à Istanbul, ville natale de Salih Dalay, après dix ans de préparation ; bague peinte par Hasan Kale ; sous-cape de Pennsylvanie, tripe de tabac turc, dominicain et du Kentucky, disent la maison, Cigar Coop et Cigarworld.de."},{"name":"Dalay Oase","color":"#8B5A2B","force":null,"wrapper":"Équateur (sélection foncée)","vitolas":[],"story":"Lancée le 15 mai 2026 à Sarrebruck ; cape foncée d''Équateur, sous-cape et tripe dominicaines, roulée à Zauberberg, dit Smokersplanet.de."},{"name":"Dalay Nicaragua","color":"#A0522D","force":null,"wrapper":"Corojo ''98 (Équateur)","vitolas":[],"story":"Roulée depuis 2023 par Luciano Meirelles à l''usine Luciano Cigars, à Estelí (Nicaragua) — sous-cape brésilienne et équatorienne, tripe entièrement nicaraguayenne, dit Cigar Coop."},{"name":"Ferruh Karakasli","color":"#4A3728","force":null,"wrapper":"San Andrés (Mexique)","vitolas":[],"story":"Avec le couturier turc Ferruh Karakaşlı, né en 1967 à Istanbul ; roulée à Zauberberg ; sous-cape de Sumatra d''Indonésie, tripe du Nicaragua et du Brésil, dit Cigarworld.de."}]',
        'Salih Dalay, born in Istanbul, founded Dalay Zigarren in Saarbrücken; the house says it is more than twenty-five years old in 2026. Its own lines are rolled at Tabacalera Zauberberg, in Santiago de los Caballeros, in the Dominican Republic, which the house calls its factory; Halfwheel describes Zauberberg as a joint venture with Dominican partners, linked to Dalay for nearly three decades, and Cigarworld.de dates its founding by Salih Dalay to 2017.

In September 2026, the catalogue comprises a light version and a dark version rolled in the Dominican Republic, Hell and Dunkel; a Honduras variant, likewise light or dark, on Corojo tobaccos; the Istanbul line, released on 8 July 2023, with a filler of Turkish tobacco, whose band carries a miniature by the Istanbul micro-painter Hasan Kale, in homage to Salih Dalay''s native city, says the house; the Oase line, launched on 15 May 2026 in Saarbrücken, inspired by the stories of Nasreddin Hodja that Salih Dalay listened to as a child, says Smokersplanet.de; and Ferruh Karakasli, with the Turkish couturier Ferruh Karakaşlı, born in 1967 in Istanbul, says Cigarworld.de.

Since 2023, the Dalay Nicaragua line has been rolled by Luciano Meirelles at the Luciano Cigars factory, in Estelí; Dalay also imports Luciano Cigars into Germany, say Cigar Coop and Halfwheel.',
        '[{"name":"Dalay Hell","color":"#C9A96E","force":"Mild","wrapper":"Undisclosed","vitolas":[],"story":"Light version from the Dominican catalogue, with a spicy aroma, says Cigarworld.de."},{"name":"Dalay Dunkel","color":"#4A3728","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Dark version, with notes of chocolate and spices, says Cigarworld.de."},{"name":"Dalay Honduras Hell","color":"#A0522D","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Light version on Honduran Corojo tobacco, says Cigarworld.de."},{"name":"Dalay Honduras Dunkel","color":"#6B4226","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Dark version on Honduran Corojo tobacco, with sweet and chocolatey notes, says Cigarworld.de."},{"name":"Dalay Istanbul","color":"#A0522D","force":null,"wrapper":"Corojo 99 (Ecuador)","vitolas":[],"story":"Released on 8 July 2023, in homage to Istanbul, Salih Dalay''s native city, after ten years of preparation; band painted by Hasan Kale; binder from Pennsylvania, filler of Turkish, Dominican and Kentucky tobacco, say the house, Cigar Coop and Cigarworld.de."},{"name":"Dalay Oase","color":"#8B5A2B","force":null,"wrapper":"Ecuador (dark selection)","vitolas":[],"story":"Launched on 15 May 2026 in Saarbrücken; dark Ecuadorian wrapper, Dominican binder and filler, rolled at Zauberberg, says Smokersplanet.de."},{"name":"Dalay Nicaragua","color":"#A0522D","force":null,"wrapper":"Corojo ''98 (Ecuador)","vitolas":[],"story":"Rolled since 2023 by Luciano Meirelles at the Luciano Cigars factory, in Estelí (Nicaragua) — Brazilian and Ecuadorian binder, entirely Nicaraguan filler, says Cigar Coop."},{"name":"Ferruh Karakasli","color":"#4A3728","force":null,"wrapper":"San Andrés (Mexico)","vitolas":[],"story":"With the Turkish couturier Ferruh Karakaşlı, born in 1967 in Istanbul; rolled at Zauberberg; Sumatra binder from Indonesia, filler from Nicaragua and Brazil, says Cigarworld.de."}]',
        'Salih Dalay, nacido en Estambul, funda en Saarbrücken Dalay Zigarren; la casa dice tener más de veinticinco años en 2026. Sus líneas propias se lían en la Tabacalera Zauberberg, en Santiago de los Caballeros, en la República Dominicana, que la casa llama su fábrica; Halfwheel describe Zauberberg como una empresa conjunta con socios dominicanos, vinculados a Dalay desde hace casi tres décadas, y Cigarworld.de data su fundación por Salih Dalay en 2017.

En septiembre de 2026, el catálogo cuenta con una versión clara y una versión oscura liadas en la República Dominicana, Hell y Dunkel; una variante Honduras, también clara u oscura, sobre tabacos Corojo; la línea Istanbul, salida el 8 de julio de 2023, con tripa de tabaco turco, cuya anilla lleva una miniatura del micropintor estambulí Hasan Kale, en homenaje a la ciudad natal de Salih Dalay, dice la casa; la línea Oase, lanzada el 15 de mayo de 2026 en Saarbrücken, inspirada en las historias de Nasreddin Hodja que Salih Dalay escuchaba de niño, dice Smokersplanet.de; y Ferruh Karakasli, con el modisto turco Ferruh Karakaşlı, nacido en 1967 en Estambul, dice Cigarworld.de.

Desde 2023, la línea Dalay Nicaragua la lía Luciano Meirelles en la fábrica de Luciano Cigars, en Estelí; Dalay también importa Luciano Cigars a Alemania, dicen Cigar Coop y Halfwheel.',
        '[{"name":"Dalay Hell","color":"#C9A96E","force":"Mild","wrapper":"No divulgada","vitolas":[],"story":"Versión clara del catálogo dominicano, de aromática especiada, dice Cigarworld.de."},{"name":"Dalay Dunkel","color":"#4A3728","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Versión oscura, con notas de chocolate y especias, dice Cigarworld.de."},{"name":"Dalay Honduras Hell","color":"#A0522D","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Versión clara sobre tabaco Corojo hondureño, dice Cigarworld.de."},{"name":"Dalay Honduras Dunkel","color":"#6B4226","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Versión oscura sobre tabaco Corojo hondureño, con notas dulces y achocolatadas, dice Cigarworld.de."},{"name":"Dalay Istanbul","color":"#A0522D","force":null,"wrapper":"Corojo 99 (Ecuador)","vitolas":[],"story":"Salida el 8 de julio de 2023, en homenaje a Estambul, ciudad natal de Salih Dalay, tras diez años de preparación; anilla pintada por Hasan Kale; capote de Pensilvania, tripa de tabaco turco, dominicano y de Kentucky, dicen la casa, Cigar Coop y Cigarworld.de."},{"name":"Dalay Oase","color":"#8B5A2B","force":null,"wrapper":"Ecuador (selección oscura)","vitolas":[],"story":"Lanzada el 15 de mayo de 2026 en Saarbrücken; capa oscura de Ecuador, capote y tripa dominicanos, liada en Zauberberg, dice Smokersplanet.de."},{"name":"Dalay Nicaragua","color":"#A0522D","force":null,"wrapper":"Corojo ''98 (Ecuador)","vitolas":[],"story":"Liada desde 2023 por Luciano Meirelles en la fábrica de Luciano Cigars, en Estelí (Nicaragua) — capote brasileño y ecuatoriano, tripa enteramente nicaragüense, dice Cigar Coop."},{"name":"Ferruh Karakasli","color":"#4A3728","force":null,"wrapper":"San Andrés (México)","vitolas":[],"story":"Con el modisto turco Ferruh Karakaşlı, nacido en 1967 en Estambul; liada en Zauberberg; capote de Sumatra de Indonesia, tripa de Nicaragua y de Brasil, dice Cigarworld.de."}]',
        'Salih Dalay, in Istanbul geboren, gründet in Saarbrücken Dalay Zigarren; das Haus gibt an, 2026 mehr als fünfundzwanzig Jahre alt zu sein. Die hauseigenen Linien werden in der Tabacalera Zauberberg in Santiago de los Caballeros in der Dominikanischen Republik gerollt, die das Haus als seine Fabrik bezeichnet; Halfwheel beschreibt Zauberberg als Gemeinschaftsunternehmen mit dominikanischen Partnern, die seit fast drei Jahrzehnten mit Dalay verbunden sind, und Cigarworld.de datiert die Gründung durch Salih Dalay auf 2017.

Im September 2026 umfasst der Katalog eine helle und eine dunkle Version, in der Dominikanischen Republik gerollt, Hell und Dunkel; eine Variante Honduras, ebenfalls hell oder dunkel, auf Corojo-Tabaken; die Linie Istanbul, erschienen am 8. Juli 2023, mit Einlage aus türkischem Tabak, deren Bauchbinde eine Miniatur des Istanbuler Mikromalers Hasan Kale trägt, als Hommage an die Geburtsstadt von Salih Dalay, so das Haus; die Linie Oase, lanciert am 15. Mai 2026 in Saarbrücken, inspiriert von den Geschichten von Nasreddin Hodja, die Salih Dalay als Kind hörte, so Smokersplanet.de; und Ferruh Karakasli, mit dem türkischen Couturier Ferruh Karakaşlı, geboren 1967 in Istanbul, so Cigarworld.de.

Seit 2023 wird die Linie Dalay Nicaragua von Luciano Meirelles in der Fabrik von Luciano Cigars in Estelí gerollt; Dalay importiert zudem Luciano Cigars nach Deutschland, so Cigar Coop und Halfwheel.',
        '[{"name":"Dalay Hell","color":"#C9A96E","force":"Mild","wrapper":"Nicht angegeben","vitolas":[],"story":"Helle Version des dominikanischen Katalogs mit würziger Aromatik, so Cigarworld.de."},{"name":"Dalay Dunkel","color":"#4A3728","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Dunkle Version mit Noten von Schokolade und Gewürzen, so Cigarworld.de."},{"name":"Dalay Honduras Hell","color":"#A0522D","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Helle Version auf honduranischem Corojo-Tabak, so Cigarworld.de."},{"name":"Dalay Honduras Dunkel","color":"#6B4226","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Dunkle Version auf honduranischem Corojo-Tabak mit süßen und schokoladigen Noten, so Cigarworld.de."},{"name":"Dalay Istanbul","color":"#A0522D","force":null,"wrapper":"Corojo 99 (Ecuador)","vitolas":[],"story":"Erschienen am 8. Juli 2023, als Hommage an Istanbul, die Geburtsstadt von Salih Dalay, nach zehn Jahren Vorbereitung; Bauchbinde von Hasan Kale gemalt; Umblatt aus Pennsylvania, Einlage aus türkischem, dominikanischem und Kentucky-Tabak, so das Haus, Cigar Coop und Cigarworld.de."},{"name":"Dalay Oase","color":"#8B5A2B","force":null,"wrapper":"Ecuador (dunkle Selektion)","vitolas":[],"story":"Lanciert am 15. Mai 2026 in Saarbrücken; dunkles Deckblatt aus Ecuador, dominikanisches Umblatt und dominikanische Einlage, gerollt in Zauberberg, so Smokersplanet.de."},{"name":"Dalay Nicaragua","color":"#A0522D","force":null,"wrapper":"Corojo ''98 (Ecuador)","vitolas":[],"story":"Seit 2023 von Luciano Meirelles in der Fabrik von Luciano Cigars in Estelí (Nicaragua) gerollt — brasilianisches und ecuadorianisches Umblatt, vollständig nicaraguanische Einlage, so Cigar Coop."},{"name":"Ferruh Karakasli","color":"#4A3728","force":null,"wrapper":"San Andrés (Mexiko)","vitolas":[],"story":"Mit dem türkischen Couturier Ferruh Karakaşlı, geboren 1967 in Istanbul; gerollt in Zauberberg; Sumatra-Umblatt aus Indonesien, Einlage aus Nicaragua und Brasilien, so Cigarworld.de."}]',
        'Salih Dalay 出生于伊斯坦布尔，在萨尔布吕肯创立了 Dalay Zigarren；该品牌称，2026年时已有超过二十五年的历史。其自有产品线在多米尼加共和国圣地亚哥-德洛斯卡瓦列罗斯的 Tabacalera Zauberberg 卷制，该品牌称这是自己的工厂；Halfwheel 将 Zauberberg 描述为与多米尼加合作伙伴共同经营的合资企业，这些伙伴与 Dalay 的联系已近三十年；Cigarworld.de 则将 Salih Dalay 创立 Zauberberg 的时间定为2017年。

2026年9月，目录中有一款浅色版本和一款深色版本，均在多米尼加共和国卷制，即 Hell 与 Dunkel；洪都拉斯版本，同样分浅色与深色，采用 Corojo 烟叶；2023年7月8日推出的 Istanbul 系列，茄芯采用土耳其烟叶，其雪茄环上有伊斯坦布尔微型画家 Hasan Kale 的一幅微型画，以向 Salih Dalay 的出生地致敬，据该品牌介绍；2026年5月15日在萨尔布吕肯推出的 Oase 系列，灵感来自 Salih Dalay 童年时听过的 Nasreddin Hodja 故事，据 Smokersplanet.de 介绍；以及 Ferruh Karakasli，与土耳其时装设计师 Ferruh Karakaşlı 合作，他于1967年出生在伊斯坦布尔，据 Cigarworld.de 介绍。

自2023年起，Dalay Nicaragua 系列由 Luciano Meirelles 在埃斯特利的 Luciano Cigars 工厂卷制；Dalay 还在德国进口 Luciano Cigars，据 Cigar Coop 与 Halfwheel 介绍。',
        '[{"name":"Dalay Hell","color":"#C9A96E","force":"Mild","wrapper":"未公开","vitolas":[],"story":"多米尼加目录中的浅色版本，带有辛香气息，据 Cigarworld.de 介绍。"},{"name":"Dalay Dunkel","color":"#4A3728","force":null,"wrapper":"未公开","vitolas":[],"story":"深色版本，带有巧克力与香料的风味，据 Cigarworld.de 介绍。"},{"name":"Dalay Honduras Hell","color":"#A0522D","force":null,"wrapper":"未公开","vitolas":[],"story":"浅色版本，采用洪都拉斯 Corojo 烟叶，据 Cigarworld.de 介绍。"},{"name":"Dalay Honduras Dunkel","color":"#6B4226","force":null,"wrapper":"未公开","vitolas":[],"story":"深色版本，采用洪都拉斯 Corojo 烟叶，带有甜味与巧克力风味，据 Cigarworld.de 介绍。"},{"name":"Dalay Istanbul","color":"#A0522D","force":null,"wrapper":"Corojo 99（厄瓜多尔）","vitolas":[],"story":"2023年7月8日推出，经十年筹备，向 Salih Dalay 的出生地伊斯坦布尔致敬；雪茄环由 Hasan Kale 绘制；茄套来自宾夕法尼亚，茄芯为土耳其、多米尼加与肯塔基烟叶，据该品牌、Cigar Coop 与 Cigarworld.de 介绍。"},{"name":"Dalay Oase","color":"#8B5A2B","force":null,"wrapper":"厄瓜多尔（深色选叶）","vitolas":[],"story":"2026年5月15日在萨尔布吕肯推出；深色厄瓜多尔茄衣，多米尼加茄套与茄芯，在 Zauberberg 卷制，据 Smokersplanet.de 介绍。"},{"name":"Dalay Nicaragua","color":"#A0522D","force":null,"wrapper":"Corojo ''98（厄瓜多尔）","vitolas":[],"story":"自2023年起由 Luciano Meirelles 在埃斯特利（尼加拉瓜）的 Luciano Cigars 工厂卷制——茄套来自巴西与厄瓜多尔，茄芯全部产自尼加拉瓜，据 Cigar Coop 介绍。"},{"name":"Ferruh Karakasli","color":"#4A3728","force":null,"wrapper":"San Andrés（墨西哥）","vitolas":[],"story":"与土耳其时装设计师 Ferruh Karakaşlı（1967年生于伊斯坦布尔）合作；在 Zauberberg 卷制；茄套为印度尼西亚的 Sumatra，茄芯来自尼加拉瓜与巴西，据 Cigarworld.de 介绍。"}]',
        'وُلد Salih Dalay في إسطنبول، وأسّس في زاربروكن Dalay Zigarren؛ وتقول الدار إنها تبلغ في عام 2026 ما يزيد على خمسة وعشرين عامًا. وتُلفّ خطوطها الخاصة في Tabacalera Zauberberg، في سانتياغو دي لوس كاباييروس بجمهورية الدومينيكان، وهي التي تقول الدار إنها مصنعها؛ ويصف Halfwheel Zauberberg بأنها مشروع مشترك مع شركاء دومينيكيين على صلة بـ Dalay منذ قرابة ثلاثة عقود، ويؤرّخ Cigarworld.de تأسيس Salih Dalay لها بعام 2017.

في سبتمبر 2026، يضمّ الكتالوج نسخة فاتحة ونسخة داكنة تُلفّان في جمهورية الدومينيكان، هما Hell وDunkel؛ ونسخة هندوراسية، فاتحة أو داكنة هي الأخرى، على تبغ Corojo؛ وخط Istanbul، الذي صدر في 8 يوليو 2023، بحشوة من التبغ التركي، وتحمل حلقته منمنمة للرسّام المجهري الإسطنبولي Hasan Kale، تكريمًا لمسقط رأس Salih Dalay، بحسب الدار؛ وخط Oase، الذي أُطلق في 15 مايو 2026 في زاربروكن، مستوحى من حكايات Nasreddin Hodja التي كان Salih Dalay يسمعها في طفولته، بحسب Smokersplanet.de؛ وFerruh Karakasli، مع مصمم الأزياء التركي Ferruh Karakaşlı، المولود عام 1967 في إسطنبول، بحسب Cigarworld.de.

ومنذ عام 2023، يُلفّ خط Dalay Nicaragua على يد Luciano Meirelles في مصنع Luciano Cigars في إستيلي؛ كما تستورد Dalay Luciano Cigars إلى ألمانيا، بحسب Cigar Coop وHalfwheel.',
        '[{"name":"Dalay Hell","color":"#C9A96E","force":"Mild","wrapper":"غير معلن","vitolas":[],"story":"النسخة الفاتحة من الكتالوج الدومينيكي، بنفحة عطرية متبّلة، بحسب Cigarworld.de."},{"name":"Dalay Dunkel","color":"#4A3728","force":null,"wrapper":"غير معلن","vitolas":[],"story":"النسخة الداكنة، بنفحات من الشوكولاتة والتوابل، بحسب Cigarworld.de."},{"name":"Dalay Honduras Hell","color":"#A0522D","force":null,"wrapper":"غير معلن","vitolas":[],"story":"النسخة الفاتحة على تبغ Corojo الهندوراسي، بحسب Cigarworld.de."},{"name":"Dalay Honduras Dunkel","color":"#6B4226","force":null,"wrapper":"غير معلن","vitolas":[],"story":"النسخة الداكنة على تبغ Corojo الهندوراسي، بنفحات حلوة وشوكولاتية، بحسب Cigarworld.de."},{"name":"Dalay Istanbul","color":"#A0522D","force":null,"wrapper":"Corojo 99 (الإكوادور)","vitolas":[],"story":"صدر في 8 يوليو 2023 تكريمًا لإسطنبول، مسقط رأس Salih Dalay، بعد عشر سنوات من الإعداد؛ حلقته مرسومة على يد Hasan Kale؛ رباط من بنسلفانيا وحشوة من تبغ تركي ودومينيكي ومن كنتاكي، بحسب الدار وCigar Coop وCigarworld.de."},{"name":"Dalay Oase","color":"#8B5A2B","force":null,"wrapper":"الإكوادور (انتقاء داكن)","vitolas":[],"story":"أُطلق في 15 مايو 2026 في زاربروكن؛ غلاف داكن من الإكوادور، ورباط وحشوة دومينيكيان، يُلفّ في Zauberberg، بحسب Smokersplanet.de."},{"name":"Dalay Nicaragua","color":"#A0522D","force":null,"wrapper":"Corojo ''98 (الإكوادور)","vitolas":[],"story":"يُلفّ منذ 2023 على يد Luciano Meirelles في مصنع Luciano Cigars في إستيلي (نيكاراغوا) — رباط برازيلي وإكوادوري، وحشوة نيكاراغوية بالكامل، بحسب Cigar Coop."},{"name":"Ferruh Karakasli","color":"#4A3728","force":null,"wrapper":"San Andrés (المكسيك)","vitolas":[],"story":"مع مصمم الأزياء التركي Ferruh Karakaşlı، المولود عام 1967 في إسطنبول؛ يُلفّ في Zauberberg؛ رباط Sumatra من إندونيسيا، وحشوة من نيكاراغوا والبرازيل، بحسب Cigarworld.de."}]')
