-- ── Tabacosta ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Tabacosta',
        'nicaragua',
        '2002 ou 2012 — Antonio Costa, Panama',
        'Usine propre — Tabacosta (Tabacos Costa Nicaragua S.A.), Estelí (Nicaragua)',
        'halfwheel « Tabacosta Adding Manuel Alonso Gran Selección at IPCPR 2016 » (fondation datée à 2012 au Panama, installation à Estelí datée à 2014, ajout de Manuel Alonso Gran Selección au catalogue) ; halfwheel « Tabacosta Bringing Costa Platinum to IPCPR 2016 » (Costa Platinum : cape habano oscuro, sous-cape équatorienne, tripe de Condega, Estelí et Jalapa, quatre formats ; 200 employés et 1,8 million de cigares par an revendiqués) ; cigarworld.de « Manuel Alonso Bundle » (consulté le 25 septembre 2026, lu directement : en septembre 2026, les formats Montescos, Nicaragua Robusto et VI sont en vente, d''autres formats étant épuisés) ; momentohumo.com « Hoy toca… COSTA Pirámides » (en espagnol ; consulté le 25 septembre 2026, lu directement : la maison est fondée par le Panaméen Antonio Costa et son fils du même prénom, en 2002 au Panama puis installée à Estelí en 2004, usine de 4 000 m² et 200 employés, quatre marques propres — Costa, Costa Maduro, Costa Platinum, Bucanero — plus des marques réalisées pour des clients tiers ; cape du Costa Pirámides de Condega, sous-cape d''Estelí, tripe de Jalapa, Condega et Estelí, force moyenne à corsée) ; humoytabaco.com « Manuel Alonso – Gran Selección (Conde) » (en espagnol ; consulté le 25 septembre 2026, lu directement : cape habano d''Équateur, sous-cape San Andrés du Mexique, tripe de Jalapa, Nicaragua ; dit la marque possédée par un Cubain, Damián Taipanes)',
        NULL,
        'Tabacos Costa Nicaragua S.A., ou Tabacosta, est fondée au Panama par Antonio Costa et son fils, prénommé lui aussi Antonio — en 2002 selon Momentohumo.com, en 2012 selon Halfwheel. Elle s''installe au Nicaragua, en 2004 ou en 2014 selon les mêmes, et bâtit à Estelí sa propre fabrique, d''environ 4 000 m², dit Momentohumo.com ; en 2016, elle revendique 200 employés et 1,8 million de cigares par an, dit Halfwheel. La maison ne dit pas qui la possède en 2026.

Momentohumo.com lui compte quatre marques propres, Costa, Costa Maduro, Costa Platinum et Bucanero, et des cigares roulés pour des clients tiers. En 2016, Tabacosta présente à l''IPCPR Costa Platinum et Manuel Alonso Gran Selección, dit Halfwheel ; Humoytabaco.com, détaillant espagnol, dit Manuel Alonso propriété du Cubain Damián Taipanes.

En septembre 2026, Cigarworld.de vend encore des Manuel Alonso en Montescos, Nicaragua Robusto et VI.',
        '[{"name":"Costa","color":"#A0522D","force":"Medium-Full","wrapper":"Nicaragua (Condega)","vitolas":[],"story":"Assemblage entièrement nicaraguayen (Condega, Estelí, Jalapa), à la force moyenne à corsée, dit Momentohumo.com."},{"name":"Costa Platinum","color":"#4A2C1A","force":null,"wrapper":"Habano oscuro (Équateur)","vitolas":[],"story":"Présentée à l''IPCPR 2016, sous-cape équatorienne et tripe de Condega, Estelí et Jalapa, en quatre formats, dit Halfwheel."},{"name":"Manuel Alonso Gran Selección","color":"#A0522D","force":null,"wrapper":"Habano (Équateur)","vitolas":[],"story":"Deux vitolas, Conde et Duques, sous-cape mexicaine de San Andrés et tripe de Jalapa, dit Humoytabaco.com."}]',
        'Tabacos Costa Nicaragua S.A., or Tabacosta, was founded in Panama by Antonio Costa and his son, also named Antonio — in 2002 according to Momentohumo.com, in 2012 according to Halfwheel. It settled in Nicaragua, in 2004 or in 2014 according to the same sources, and built its own factory in Estelí, of about 4,000 m², says Momentohumo.com; in 2016, it claimed 200 employees and 1.8 million cigars a year, says Halfwheel. The house does not say who owns it in 2026.

Momentohumo.com credits it with four brands of its own, Costa, Costa Maduro, Costa Platinum and Bucanero, and with cigars rolled for third-party clients. In 2016, Tabacosta presented Costa Platinum and Manuel Alonso Gran Selección at the IPCPR, says Halfwheel; Humoytabaco.com, a Spanish retailer, says Manuel Alonso is owned by the Cuban Damián Taipanes.

In September 2026, Cigarworld.de still sells Manuel Alonso in Montescos, Nicaragua Robusto and VI.',
        '[{"name":"Costa","color":"#A0522D","force":"Medium-Full","wrapper":"Nicaragua (Condega)","vitolas":[],"story":"Entirely Nicaraguan blend (Condega, Estelí, Jalapa), of medium to full strength, says Momentohumo.com."},{"name":"Costa Platinum","color":"#4A2C1A","force":null,"wrapper":"Habano oscuro (Ecuador)","vitolas":[],"story":"Presented at the IPCPR 2016, Ecuadorian binder and filler from Condega, Estelí and Jalapa, in four formats, says Halfwheel."},{"name":"Manuel Alonso Gran Selección","color":"#A0522D","force":null,"wrapper":"Habano (Ecuador)","vitolas":[],"story":"Two vitolas, Conde and Duques, Mexican San Andrés binder and filler from Jalapa, says Humoytabaco.com."}]',
        'Antonio Costa y su hijo, llamado también Antonio, fundan en Panamá Tabacos Costa Nicaragua S.A., o Tabacosta — en 2002 según Momentohumo.com, en 2012 según Halfwheel. La sociedad se instala en Nicaragua, en 2004 o en 2014 según las mismas fuentes, y construye en Estelí su propia fábrica, de unos 4000 m², dice Momentohumo.com; en 2016, afirma tener 200 empleados y 1,8 millones de puros al año, dice Halfwheel. La casa no dice quién la posee en 2026.

Momentohumo.com le atribuye cuatro marcas propias, Costa, Costa Maduro, Costa Platinum y Bucanero, y puros liados para clientes terceros. En 2016, Tabacosta presenta en la IPCPR Costa Platinum y Manuel Alonso Gran Selección, dice Halfwheel; Humoytabaco.com, minorista español, dice que Manuel Alonso es propiedad del cubano Damián Taipanes.

En septiembre de 2026, Cigarworld.de sigue vendiendo Manuel Alonso en Montescos, Nicaragua Robusto y VI.',
        '[{"name":"Costa","color":"#A0522D","force":"Medium-Full","wrapper":"Nicaragua (Condega)","vitolas":[],"story":"Liga enteramente nicaragüense (Condega, Estelí, Jalapa), de fuerza media a fuerte, dice Momentohumo.com."},{"name":"Costa Platinum","color":"#4A2C1A","force":null,"wrapper":"Habano oscuro (Ecuador)","vitolas":[],"story":"Presentada en la IPCPR 2016, capote ecuatoriano y tripa de Condega, Estelí y Jalapa, en cuatro formatos, dice Halfwheel."},{"name":"Manuel Alonso Gran Selección","color":"#A0522D","force":null,"wrapper":"Habano (Ecuador)","vitolas":[],"story":"Dos vitolas, Conde y Duques, capote mexicano de San Andrés y tripa de Jalapa, dice Humoytabaco.com."}]',
        'Antonio Costa und sein Sohn, ebenfalls Antonio genannt, gründen in Panama Tabacos Costa Nicaragua S.A., oder Tabacosta — 2002 laut Momentohumo.com, 2012 laut Halfwheel. Das Unternehmen lässt sich in Nicaragua nieder, 2004 oder 2014 laut denselben Quellen, und baut in Estelí seine eigene Fabrik mit etwa 4000 m², so Momentohumo.com; 2016 nimmt es für sich 200 Beschäftigte und 1,8 Millionen Zigarren pro Jahr in Anspruch, so Halfwheel. Das Haus sagt nicht, wem es 2026 gehört.

Momentohumo.com rechnet ihm vier eigene Marken zu, Costa, Costa Maduro, Costa Platinum und Bucanero, sowie für Drittkunden gerollte Zigarren. 2016 stellt Tabacosta auf der IPCPR Costa Platinum und Manuel Alonso Gran Selección vor, so Halfwheel; Humoytabaco.com, ein spanischer Einzelhändler, gibt den Kubaner Damián Taipanes als Eigentümer von Manuel Alonso an.

Im September 2026 verkauft Cigarworld.de weiterhin Manuel Alonso in Montescos, Nicaragua Robusto und VI.',
        '[{"name":"Costa","color":"#A0522D","force":"Medium-Full","wrapper":"Nicaragua (Condega)","vitolas":[],"story":"Vollständig nicaraguanische Mischung (Condega, Estelí, Jalapa), von mittlerer bis kräftiger Stärke, so Momentohumo.com."},{"name":"Costa Platinum","color":"#4A2C1A","force":null,"wrapper":"Habano oscuro (Ecuador)","vitolas":[],"story":"Auf der IPCPR 2016 vorgestellt, ecuadorianisches Umblatt und Einlage aus Condega, Estelí und Jalapa, in vier Formaten, so Halfwheel."},{"name":"Manuel Alonso Gran Selección","color":"#A0522D","force":null,"wrapper":"Habano (Ecuador)","vitolas":[],"story":"Zwei Formate, Conde und Duques, mexikanisches San-Andrés-Umblatt und Einlage aus Jalapa, so Humoytabaco.com."}]',
        'Tabacos Costa Nicaragua S.A.，即 Tabacosta，由 Antonio Costa 与其子（同样名叫 Antonio）在巴拿马创立——据 Momentohumo.com 介绍为2002年，据 Halfwheel 介绍为2012年。公司落户尼加拉瓜的时间，据同样的来源为2004年或2014年；并在埃斯特利建起自有工厂，面积约4000 m²，据 Momentohumo.com 介绍；2016年，公司声称拥有200名员工、年产1.8百万支雪茄，据 Halfwheel 介绍。该公司未说明2026年时的所有者是谁。

Momentohumo.com 列出其四个自有品牌，即 Costa、Costa Maduro、Costa Platinum 与 Bucanero，并称其为第三方客户卷制雪茄。2016年，Tabacosta 在 IPCPR 上展示 Costa Platinum 与 Manuel Alonso Gran Selección，据 Halfwheel 介绍；西班牙零售商 Humoytabaco.com 称 Manuel Alonso 归古巴人 Damián Taipanes 所有。

2026年9月，Cigarworld.de 仍在销售 Manuel Alonso，规格为 Montescos、Nicaragua Robusto 与 VI。',
        '[{"name":"Costa","color":"#A0522D","force":"Medium-Full","wrapper":"尼加拉瓜（孔德加）","vitolas":[],"story":"完全产自尼加拉瓜的拼配（孔德加、埃斯特利、哈拉帕），强度中等至浓烈，据 Momentohumo.com 介绍。"},{"name":"Costa Platinum","color":"#4A2C1A","force":null,"wrapper":"Habano oscuro（厄瓜多尔）","vitolas":[],"story":"2016年在 IPCPR 上展示；茄套来自厄瓜多尔，茄芯来自孔德加、埃斯特利与哈拉帕，共四种规格，据 Halfwheel 介绍。"},{"name":"Manuel Alonso Gran Selección","color":"#A0522D","force":null,"wrapper":"Habano（厄瓜多尔）","vitolas":[],"story":"两种规格，Conde 与 Duques，茄套为墨西哥的 San Andrés，茄芯来自哈拉帕，据 Humoytabaco.com 介绍。"}]',
        'أسّس Antonio Costa وابنه، الذي يحمل الاسم نفسه Antonio، شركة Tabacos Costa Nicaragua S.A. أو Tabacosta في بنما — في عام 2002 بحسب Momentohumo.com، وفي عام 2012 بحسب Halfwheel. ثم استقرت الشركة في نيكاراغوا، في عام 2004 أو 2014 بحسب المصادر نفسها، وبنت في إستيلي مصنعها الخاص بمساحة تبلغ نحو 4000 m²، بحسب Momentohumo.com؛ وفي عام 2016، أعلنت أن لديها 200 موظف وإنتاجًا قدره 1.8 مليون سيجار في السنة، بحسب Halfwheel. ولا تقول الدار من يملكها في عام 2026.

ويحصي لها Momentohumo.com أربع علامات خاصة، هي Costa وCosta Maduro وCosta Platinum وBucanero، إضافة إلى سيجار يُلفّ لحساب عملاء من الغير. وفي عام 2016، قدّمت Tabacosta في IPCPR كلًّا من Costa Platinum وManuel Alonso Gran Selección، بحسب Halfwheel؛ ويقول Humoytabaco.com، وهو تاجر تجزئة إسباني، إن Manuel Alonso ملك للكوبي Damián Taipanes.

وفي سبتمبر 2026، لا يزال Cigarworld.de يبيع Manuel Alonso بقياسات Montescos وNicaragua Robusto وVI.',
        '[{"name":"Costa","color":"#A0522D","force":"Medium-Full","wrapper":"نيكاراغوا (كونديغا)","vitolas":[],"story":"خلطة نيكاراغوية بالكامل (كونديغا وإستيلي وخالابا)، متوسطة القوة إلى قوية، بحسب Momentohumo.com."},{"name":"Costa Platinum","color":"#4A2C1A","force":null,"wrapper":"Habano oscuro (الإكوادور)","vitolas":[],"story":"قُدِّمت في IPCPR عام 2016؛ رباط إكوادوري وحشوة من كونديغا وإستيلي وخالابا، في أربعة قياسات، بحسب Halfwheel."},{"name":"Manuel Alonso Gran Selección","color":"#A0522D","force":null,"wrapper":"Habano (الإكوادور)","vitolas":[],"story":"قياسان، Conde وDuques، ورباط San Andrés المكسيكي وحشوة من خالابا، بحسب Humoytabaco.com."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Casa de Garcia ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Casa de Garcia',
        'dominican',
        'Non précisée — Altadis U.S.A., La Romana',
        'Tabacalera de García, La Romana, Rép. dominicaine ; lignes Centenario au Nicaragua, avec la famille Plasencia',
        'altadisusa.com « Casa de Garcia » (lu le 30 septembre 2026 : cigares roulés à la main à prix accessible, en plusieurs forces ; six lignes ; aucune date de lancement) ; altadisusa.com « Casa de Garcia Connecticut Blend » (lu le 30 septembre 2026 : cape connecticut shade, sous-cape connecticut, tripe dominicaine et hondurienne, profil doux ; République dominicaine ; sept vitolas, de la Corona au Colossal) ; altadisusa.com « Casa de Garcia Maduro Blend » (lu le 30 septembre 2026 : cape et sous-cape connecticut broadleaf, tripe dominicaine et hondurienne, notes de cacao, de chocolat et de cèdre ; République dominicaine) ; altadisusa.com « Casa de Garcia Sumatra Blend » (lu le 30 septembre 2026 : cape sumatra, sous-cape connecticut broadleaf, tripe dominicaine et hondurienne, force douce, combustion lente ; République dominicaine) ; altadisusa.com « Casa de Garcia Nicaragua » (lu le 30 septembre 2026 : cape habano 2000 nicaraguayenne, sous-cape connecticut broadleaf, tripe nicaraguayenne, broadleaf et colombienne, plus corsée ; roulée en République dominicaine ; sept vitolas) ; altadisusa.com « Casa De Garcia Centenario Red Label » (lu le 30 septembre 2026 : façonnée au Nicaragua avec la famille Plasencia, expression moderne de la marque ; cape habano équatorienne, sous-cape et tripe nicaraguayennes ; force 4 sur l''échelle de la maison ; quatre vitolas, du Robusto au Magnum) ; altadisusa.com « Casa De Garcia Centenario Gold Label » (lu le 30 septembre 2026 : même façon ; cape connecticut équatorienne, sous-cape et tripe nicaraguayennes ; force 3 sur l''échelle de la maison ; quatre vitolas) ; cigarworld.de « Casa de Garcia » (lu le 30 septembre 2026, en anglais : roulée à la Tabacalera de García, La Romana ; fabrique établie par Pepe García, exilé cubain de la famille Menéndez, qui tenait H. Upmann avant la révolution) ; onlineshop-helgoland.de « Casa de Garcia » (lu le 30 septembre 2026, en anglais : produite à la Tabacalera de García, La Romana ; marque fondée par Pepe García, descendant de la famille Menéndez)',
        NULL,
        'Casa de Garcia est une marque d''Altadis U.S.A., roulée à la main à la Tabacalera de García, à La Romana, en République dominicaine, disent Cigarworld.de et Onlineshop-Helgoland. Cigarworld.de rattache la fabrique à Pepe García, exilé cubain de la famille Menéndez, qui tenait H. Upmann avant la révolution ; Onlineshop-Helgoland dit la marque elle-même fondée par lui. Altadis U.S.A. la présente comme une gamme de cigares roulés à la main à prix accessible, en plusieurs forces, et ne date pas son lancement.

En septembre 2026, le catalogue compte six lignes, dit la maison. Quatre sont roulées en République dominicaine : Connecticut Blend, à cape connecticut shade sur une sous-cape connecticut et une tripe dominicaine et hondurienne ; Maduro Blend, à cape et sous-cape broadleaf connecticut ; Sumatra Blend, à cape sumatra sur une sous-cape broadleaf ; et Nicaragua, à cape habano nicaraguayenne, sous-cape broadleaf et tripe nicaraguayenne, broadleaf et colombienne. Connecticut Blend et Nicaragua se déclinent en sept vitolas, de la Corona au Colossal.

Les deux lignes Centenario, Red Label et Gold Label, sont façonnées au Nicaragua avec la famille Plasencia, dit la maison, qui les présente comme une expression moderne de la marque : la première sous une cape habano équatorienne, la seconde sous une cape connecticut équatorienne, toutes deux sur une sous-cape et une tripe nicaraguayennes, en quatre vitolas, du Robusto au Magnum.',
        '[{"name":"Connecticut Blend","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"Cape connecticut shade et sous-cape connecticut sur une tripe dominicaine et hondurienne, au profil doux, dit la maison."},{"name":"Maduro Blend","color":"#4A2C1A","force":null,"wrapper":"Connecticut Broadleaf","vitolas":[],"story":"Cape et sous-cape broadleaf connecticut sur une tripe dominicaine et hondurienne, aux notes de cacao et de cèdre, dit la maison."},{"name":"Sumatra Blend","color":"#8B5A2B","force":"Mild","wrapper":"Sumatra","vitolas":[],"story":"Cape sumatra et sous-cape broadleaf connecticut sur une tripe dominicaine et hondurienne, à la combustion lente, dit la maison."},{"name":"Nicaragua","color":"#6B4226","force":null,"wrapper":"Habano nicaraguayen","vitolas":[],"story":"Roulée en République dominicaine sous une cape habano nicaraguayenne, sur une sous-cape broadleaf et une tripe nicaraguayenne, broadleaf et colombienne ; plus corsée que les autres lignes, dit la maison."},{"name":"Centenario Red Label","color":"#6B4226","force":"Medium-Full","wrapper":"Habano équatorien","vitolas":[],"story":"Façonnée au Nicaragua avec la famille Plasencia, sur une sous-cape et une tripe nicaraguayennes, dit la maison."},{"name":"Centenario Gold Label","color":"#C9A96E","force":"Medium","wrapper":"Connecticut équatorien","vitolas":[],"story":"Façonnée elle aussi au Nicaragua avec la famille Plasencia, sur une sous-cape et une tripe nicaraguayennes, dit la maison."}]',
        'Casa de Garcia is a brand of Altadis U.S.A., rolled by hand at Tabacalera de García, in La Romana, in the Dominican Republic, say Cigarworld.de and Onlineshop-Helgoland. Cigarworld.de links the factory to Pepe García, a Cuban exile of the Menéndez family, who ran H. Upmann before the revolution; Onlineshop-Helgoland says the brand itself was founded by him. Altadis U.S.A. presents it as a range of affordably priced hand-rolled cigars, in several strengths, and does not date its launch.

In September 2026, the catalogue comprises six lines, says the house. Four are rolled in the Dominican Republic: Connecticut Blend, with a Connecticut shade wrapper over a Connecticut binder and a Dominican and Honduran filler; Maduro Blend, with a Connecticut broadleaf wrapper and binder; Sumatra Blend, with a Sumatra wrapper over a broadleaf binder; and Nicaragua, with a Nicaraguan habano wrapper, a broadleaf binder and a Nicaraguan, broadleaf and Colombian filler. Connecticut Blend and Nicaragua come in seven vitolas, from the Corona to the Colossal.

The two Centenario lines, Red Label and Gold Label, are crafted in Nicaragua with the Plasencia family, says the house, which presents them as a modern expression of the brand: the first under an Ecuadorian habano wrapper, the second under an Ecuadorian Connecticut wrapper, both over a Nicaraguan binder and filler, in four vitolas, from the Robusto to the Magnum.',
        '[{"name":"Connecticut Blend","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"Connecticut shade wrapper and Connecticut binder over a Dominican and Honduran filler, with a mild profile, says the house."},{"name":"Maduro Blend","color":"#4A2C1A","force":null,"wrapper":"Connecticut Broadleaf","vitolas":[],"story":"Connecticut broadleaf wrapper and binder over a Dominican and Honduran filler, with notes of cocoa and cedar, says the house."},{"name":"Sumatra Blend","color":"#8B5A2B","force":"Mild","wrapper":"Sumatra","vitolas":[],"story":"Sumatra wrapper and Connecticut broadleaf binder over a Dominican and Honduran filler, with a slow burn, says the house."},{"name":"Nicaragua","color":"#6B4226","force":null,"wrapper":"Nicaraguan Habano","vitolas":[],"story":"Rolled in the Dominican Republic under a Nicaraguan habano wrapper, over a broadleaf binder and a Nicaraguan, broadleaf and Colombian filler; fuller-bodied than the other lines, says the house."},{"name":"Centenario Red Label","color":"#6B4226","force":"Medium-Full","wrapper":"Ecuadorian Habano","vitolas":[],"story":"Crafted in Nicaragua with the Plasencia family, over a Nicaraguan binder and filler, says the house."},{"name":"Centenario Gold Label","color":"#C9A96E","force":"Medium","wrapper":"Ecuadorian Connecticut","vitolas":[],"story":"Also crafted in Nicaragua with the Plasencia family, over a Nicaraguan binder and filler, says the house."}]',
        'Casa de Garcia es una marca de Altadis U.S.A., liada a mano en la Tabacalera de García, en La Romana, en la República Dominicana, dicen Cigarworld.de y Onlineshop-Helgoland. Cigarworld.de vincula la fábrica con Pepe García, exiliado cubano de la familia Menéndez, que dirigía H. Upmann antes de la revolución; Onlineshop-Helgoland dice que la propia marca fue fundada por él. Altadis U.S.A. la presenta como una gama de puros liados a mano de precio accesible, en varias fuerzas, y no data su lanzamiento.

En septiembre de 2026, el catálogo cuenta con seis líneas, dice la casa. Cuatro se lían en la República Dominicana: Connecticut Blend, con capa Connecticut Shade sobre un capote Connecticut y una tripa dominicana y hondureña; Maduro Blend, con capa y capote Connecticut Broadleaf; Sumatra Blend, con capa Sumatra sobre un capote broadleaf; y Nicaragua, con capa habano nicaragüense, capote broadleaf y tripa nicaragüense, broadleaf y colombiana. Connecticut Blend y Nicaragua se ofrecen en siete vitolas, de Corona a Colossal.

Las dos líneas Centenario, Red Label y Gold Label, se elaboran en Nicaragua con la familia Plasencia, dice la casa, que las presenta como una expresión moderna de la marca: la primera bajo una capa habano ecuatoriana, la segunda bajo una capa Connecticut ecuatoriana, ambas sobre un capote y una tripa nicaragüenses, en cuatro vitolas, de Robusto a Magnum.',
        '[{"name":"Connecticut Blend","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"Capa Connecticut Shade y capote Connecticut sobre una tripa dominicana y hondureña, de perfil suave, dice la casa."},{"name":"Maduro Blend","color":"#4A2C1A","force":null,"wrapper":"Connecticut Broadleaf","vitolas":[],"story":"Capa y capote Connecticut Broadleaf sobre una tripa dominicana y hondureña, con notas de cacao y cedro, dice la casa."},{"name":"Sumatra Blend","color":"#8B5A2B","force":"Mild","wrapper":"Sumatra","vitolas":[],"story":"Capa Sumatra y capote Connecticut Broadleaf sobre una tripa dominicana y hondureña, de combustión lenta, dice la casa."},{"name":"Nicaragua","color":"#6B4226","force":null,"wrapper":"Habano nicaragüense","vitolas":[],"story":"Liada en la República Dominicana bajo una capa habano nicaragüense, sobre un capote broadleaf y una tripa nicaragüense, broadleaf y colombiana; de más cuerpo que las demás líneas, dice la casa."},{"name":"Centenario Red Label","color":"#6B4226","force":"Medium-Full","wrapper":"Habano ecuatoriano","vitolas":[],"story":"Elaborada en Nicaragua con la familia Plasencia, sobre un capote y una tripa nicaragüenses, dice la casa."},{"name":"Centenario Gold Label","color":"#C9A96E","force":"Medium","wrapper":"Connecticut ecuatoriano","vitolas":[],"story":"Elaborada también en Nicaragua con la familia Plasencia, sobre un capote y una tripa nicaragüenses, dice la casa."}]',
        'Casa de Garcia ist eine Marke von Altadis U.S.A., die in der Tabacalera de García in La Romana in der Dominikanischen Republik von Hand gerollt wird, so Cigarworld.de und Onlineshop-Helgoland. Cigarworld.de bringt die Fabrik mit Pepe García in Verbindung, einem Exilkubaner aus der Familie Menéndez, der vor der Revolution H. Upmann führte; Onlineshop-Helgoland sagt, die Marke selbst sei von ihm gegründet worden. Altadis U.S.A. stellt sie als Sortiment handgerollter Zigarren zu erschwinglichem Preis in mehreren Stärken vor und datiert ihre Einführung nicht.

Im September 2026 umfasst der Katalog sechs Linien, so das Haus. Vier davon werden in der Dominikanischen Republik gerollt: Connecticut Blend, mit Deckblatt Connecticut Shade auf einem Umblatt Connecticut und einer dominikanischen und honduranischen Einlage; Maduro Blend, mit Deckblatt und Umblatt Connecticut Broadleaf; Sumatra Blend, mit Deckblatt Sumatra auf einem Umblatt Broadleaf; und Nicaragua, mit Deckblatt Habano aus Nicaragua, Umblatt Broadleaf und einer Einlage aus nicaraguanischem Tabak, Broadleaf und kolumbianischem Tabak. Connecticut Blend und Nicaragua gibt es in sieben Vitolas, von Corona bis Colossal.

Die beiden Centenario-Linien, Red Label und Gold Label, werden in Nicaragua zusammen mit der Familie Plasencia gefertigt, so das Haus, das sie als moderne Ausdrucksform der Marke vorstellt: die erste mit Deckblatt Habano aus Ecuador, die zweite mit Deckblatt Connecticut aus Ecuador, beide auf Umblatt und Einlage aus Nicaragua, in vier Vitolas, von Robusto bis Magnum.',
        '[{"name":"Connecticut Blend","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"Deckblatt Connecticut Shade und Umblatt Connecticut auf einer dominikanischen und honduranischen Einlage, mit mildem Profil, so das Haus."},{"name":"Maduro Blend","color":"#4A2C1A","force":null,"wrapper":"Connecticut Broadleaf","vitolas":[],"story":"Deckblatt und Umblatt Connecticut Broadleaf auf einer dominikanischen und honduranischen Einlage, mit Noten von Kakao und Zedernholz, so das Haus."},{"name":"Sumatra Blend","color":"#8B5A2B","force":"Mild","wrapper":"Sumatra","vitolas":[],"story":"Deckblatt Sumatra und Umblatt Connecticut Broadleaf auf einer dominikanischen und honduranischen Einlage, mit langsamem Abbrand, so das Haus."},{"name":"Nicaragua","color":"#6B4226","force":null,"wrapper":"Habano aus Nicaragua","vitolas":[],"story":"In der Dominikanischen Republik gerollt, mit Deckblatt Habano aus Nicaragua, auf einem Umblatt Broadleaf und einer Einlage aus nicaraguanischem Tabak, Broadleaf und kolumbianischem Tabak; kräftiger als die übrigen Linien, so das Haus."},{"name":"Centenario Red Label","color":"#6B4226","force":"Medium-Full","wrapper":"Habano aus Ecuador","vitolas":[],"story":"In Nicaragua zusammen mit der Familie Plasencia gefertigt, auf Umblatt und Einlage aus Nicaragua, so das Haus."},{"name":"Centenario Gold Label","color":"#C9A96E","force":"Medium","wrapper":"Connecticut aus Ecuador","vitolas":[],"story":"Ebenfalls in Nicaragua zusammen mit der Familie Plasencia gefertigt, auf Umblatt und Einlage aus Nicaragua, so das Haus."}]',
        'Casa de Garcia是Altadis U.S.A.旗下品牌，在多米尼加共和国拉罗马纳的Tabacalera de García手工卷制，据Cigarworld.de与Onlineshop-Helgoland介绍。Cigarworld.de将该工厂与Pepe García联系起来，此人是Menéndez家族的古巴流亡者，革命前曾经营H. Upmann；Onlineshop-Helgoland称品牌本身由他创立。Altadis U.S.A.将其介绍为一系列价格亲民的手工卷制雪茄，涵盖多种力度，并未给出其推出日期。

2026年9月，据品牌方介绍，目录共有六个系列。其中四个系列在多米尼加共和国卷制：Connecticut Blend，Connecticut shade茄衣覆于Connecticut茄套与多米尼加、洪都拉斯茄芯之上；Maduro Blend，茄衣与茄套均为Connecticut broadleaf；Sumatra Blend，Sumatra茄衣覆于broadleaf茄套之上；以及Nicaragua，尼加拉瓜habano茄衣覆于broadleaf茄套与尼加拉瓜、broadleaf、哥伦比亚茄芯之上。Connecticut Blend与Nicaragua均有七种规格，从Corona到Colossal。

Centenario的两个系列Red Label与Gold Label，据品牌方介绍，是与Plasencia家族在尼加拉瓜共同制作的，品牌方将它们介绍为该品牌的现代演绎：前者采用厄瓜多尔habano茄衣，后者采用厄瓜多尔Connecticut茄衣，二者均覆于尼加拉瓜茄套与茄芯之上，均有四种规格，从Robusto到Magnum。',
        '[{"name":"Connecticut Blend","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"Connecticut shade茄衣与Connecticut茄套，覆于多米尼加与洪都拉斯茄芯之上，风味温和，据品牌方介绍。"},{"name":"Maduro Blend","color":"#4A2C1A","force":null,"wrapper":"Connecticut Broadleaf","vitolas":[],"story":"Connecticut broadleaf茄衣与茄套，覆于多米尼加与洪都拉斯茄芯之上，带有可可与雪松木的风味，据品牌方介绍。"},{"name":"Sumatra Blend","color":"#8B5A2B","force":"Mild","wrapper":"Sumatra","vitolas":[],"story":"Sumatra茄衣与Connecticut broadleaf茄套，覆于多米尼加与洪都拉斯茄芯之上，燃烧缓慢，据品牌方介绍。"},{"name":"Nicaragua","color":"#6B4226","force":null,"wrapper":"尼加拉瓜Habano","vitolas":[],"story":"在多米尼加共和国卷制，尼加拉瓜habano茄衣覆于broadleaf茄套与尼加拉瓜、broadleaf、哥伦比亚茄芯之上；比其他系列更为浓郁，据品牌方介绍。"},{"name":"Centenario Red Label","color":"#6B4226","force":"Medium-Full","wrapper":"厄瓜多尔Habano","vitolas":[],"story":"在尼加拉瓜与Plasencia家族共同制作，覆于尼加拉瓜茄套与茄芯之上，据品牌方介绍。"},{"name":"Centenario Gold Label","color":"#C9A96E","force":"Medium","wrapper":"厄瓜多尔Connecticut","vitolas":[],"story":"同样在尼加拉瓜与Plasencia家族共同制作，覆于尼加拉瓜茄套与茄芯之上，据品牌方介绍。"}]',
        'Casa de Garcia هي علامة Altadis U.S.A.، تُلفّ يدويًا في Tabacalera de García، في لا رومانا بجمهورية الدومينيكان، بحسب Cigarworld.de وOnlineshop-Helgoland. ويربط Cigarworld.de المصنع بـPepe García، وهو منفيّ كوبي من عائلة Menéndez كان يدير H. Upmann قبل الثورة؛ ويقول Onlineshop-Helgoland إن العلامة نفسها من تأسيسه. وتقدّمها Altadis U.S.A. على أنها تشكيلة من السيجار الملفوف يدويًا بسعر في المتناول، بدرجات قوة متعددة، ولا تحدّد تاريخ إطلاقها.

في سبتمبر 2026، يضمّ الكتالوج ستة خطوط، بحسب الدار. أربعة منها تُلفّ في جمهورية الدومينيكان: Connecticut Blend، بغلاف Connecticut shade فوق رباط Connecticut وحشوة دومينيكية وهندوراسية؛ وMaduro Blend، بغلاف ورباط Connecticut broadleaf؛ وSumatra Blend، بغلاف Sumatra فوق رباط broadleaf؛ وNicaragua، بغلاف habano نيكاراغوي، ورباط broadleaf، وحشوة نيكاراغوية وbroadleaf وكولومبية. ويتوفر Connecticut Blend وNicaragua في سبعة مقاسات، من Corona إلى Colossal.

يُصنع خطّا Centenario، Red Label وGold Label، في نيكاراغوا مع عائلة Plasencia، بحسب الدار، التي تقدّمهما على أنهما تعبير حديث عن العلامة: الأول بغلاف habano إكوادوري، والثاني بغلاف Connecticut إكوادوري، وكلاهما على رباط وحشوة نيكاراغويين، في أربعة مقاسات، من Robusto إلى Magnum.',
        '[{"name":"Connecticut Blend","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"غلاف Connecticut shade ورباط Connecticut على حشوة دومينيكية وهندوراسية، بطابع خفيف، بحسب الدار."},{"name":"Maduro Blend","color":"#4A2C1A","force":null,"wrapper":"Connecticut Broadleaf","vitolas":[],"story":"غلاف ورباط Connecticut broadleaf على حشوة دومينيكية وهندوراسية، بنكهات الكاكاو وخشب الأرز، بحسب الدار."},{"name":"Sumatra Blend","color":"#8B5A2B","force":"Mild","wrapper":"Sumatra","vitolas":[],"story":"غلاف Sumatra ورباط Connecticut broadleaf على حشوة دومينيكية وهندوراسية، باحتراق بطيء، بحسب الدار."},{"name":"Nicaragua","color":"#6B4226","force":null,"wrapper":"Habano نيكاراغوي","vitolas":[],"story":"تُلفّ في جمهورية الدومينيكان بغلاف habano نيكاراغوي، على رباط broadleaf وحشوة نيكاراغوية وbroadleaf وكولومبية؛ أشدّ قوةً من الخطوط الأخرى، بحسب الدار."},{"name":"Centenario Red Label","color":"#6B4226","force":"Medium-Full","wrapper":"Habano إكوادوري","vitolas":[],"story":"تُصنع في نيكاراغوا مع عائلة Plasencia، على رباط وحشوة نيكاراغويين، بحسب الدار."},{"name":"Centenario Gold Label","color":"#C9A96E","force":"Medium","wrapper":"Connecticut إكوادوري","vitolas":[],"story":"تُصنع هي أيضًا في نيكاراغوا مع عائلة Plasencia، على رباط وحشوة نيكاراغويين، بحسب الدار."}]')
