INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Dominican Estates',
        'dominican',
        'Non précisée — José A. Seijas, La Romana',
        'Tabacalera de García, La Romana, Rép. dominicaine',
        'cigarworld.de « Dominican Estates » (lu le 30 septembre 2026, en anglais : marque de José Seijas, chef de fabrication de la Tabacalera Garcia, à qui le site attribue aussi la VegaFina Limitada de 2009 ; cape Connecticut Shade, sous-cape broadleaf américaine, tripe colombienne et dominicaine ; force douce ; dix vitolas, de la Petit Corona au Churchill, dont une Corona en tube de verre ; série créée au catalogue le 28 septembre 2005) ; halfwheel.com « José Seijas, longtime Tabacalera de García head, Matilde founder, passes away at 74 » (2024, lue par son titre : chef de longue date de la Tabacalera de García, fondateur de Matilde, mort à 74 ans)',
        NULL,
        'Dominican Estates est la marque de José A. Seijas, chef de fabrication de la Tabacalera de García, à La Romana, en République dominicaine, dit Cigarworld.de, qui lui attribue aussi la VegaFina Limitada de 2009 ; Halfwheel, qui le dit longtemps à la tête de cette fabrique, le nomme aussi fondateur de la marque Matilde. Le lancement de Dominican Estates n''est pas daté ; Cigarworld.de la tient à son catalogue depuis le 28 septembre 2005.

L''assemblage unique marie une cape connecticut shade, une sous-cape broadleaf américaine et une tripe de tabacs colombiens et dominicains, de force douce, dit Cigarworld.de ; il se décline en dix vitolas, de la Petit Corona au Churchill, avec une Short Magnum et une Titan de cepo 60 et une Corona en tube de verre.

José A. Seijas meurt en 2024, à 74 ans, dit Halfwheel ; qui reprend la marque après lui n''est pas dit. En septembre 2026, Cigarworld.de la vend encore.',
        '[{"name":"Dominican Estates","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"Cape connecticut shade, sous-cape broadleaf américaine et tripe colombienne et dominicaine, de force douce, en dix vitolas, dit Cigarworld.de."}]',
        'Dominican Estates is the brand of José A. Seijas, head of production at Tabacalera de García, in La Romana, in the Dominican Republic, says Cigarworld.de, which also attributes to him the 2009 VegaFina Limitada; Halfwheel, which describes him as the longtime head of that factory, also names him founder of the Matilde brand. The launch of Dominican Estates is not dated; Cigarworld.de has had it in its catalogue since 28 September 2005.

The single blend marries a Connecticut shade wrapper, an American broadleaf binder and a filler of Colombian and Dominican tobaccos, mild in strength, says Cigarworld.de; it comes in ten vitolas, from the Petit Corona to the Churchill, with a Short Magnum and a Titan of cepo 60 and a Corona in a glass tube.

José A. Seijas died in 2024, aged 74, says Halfwheel; who took over the brand after him is not stated. In September 2026, Cigarworld.de still sells it.',
        '[{"name":"Dominican Estates","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"Connecticut shade wrapper, American broadleaf binder and Colombian and Dominican filler, mild in strength, in ten vitolas, says Cigarworld.de."}]',
        'Dominican Estates es la marca de José A. Seijas, jefe de producción de la Tabacalera de García, en La Romana, en la República Dominicana, dice Cigarworld.de, que también le atribuye la VegaFina Limitada de 2009; Halfwheel, que lo sitúa largo tiempo al frente de esa fábrica, lo señala también como fundador de la marca Matilde. El lanzamiento de Dominican Estates no está fechado; Cigarworld.de la tiene en su catálogo desde el 28 de septiembre de 2005.

La única mezcla combina una capa Connecticut Shade, un capote broadleaf estadounidense y una tripa de tabacos colombianos y dominicanos, de fuerza suave, dice Cigarworld.de; se ofrece en diez vitolas, de Petit Corona a Churchill, con una Short Magnum y una Titan de cepo 60 y una Corona en tubo de vidrio.

José A. Seijas murió en 2024, a los 74 años, dice Halfwheel; no se dice quién se hizo cargo de la marca después de él. En septiembre de 2026, Cigarworld.de todavía la vende.',
        '[{"name":"Dominican Estates","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"Capa Connecticut Shade, capote broadleaf estadounidense y tripa colombiana y dominicana, de fuerza suave, en diez vitolas, dice Cigarworld.de."}]',
        'Dominican Estates ist die Marke von José A. Seijas, Produktionsleiter der Tabacalera de García in La Romana in der Dominikanischen Republik, so Cigarworld.de, das ihm auch die VegaFina Limitada von 2009 zuschreibt; Halfwheel, das ihn als langjährigen Leiter dieser Fabrik bezeichnet, nennt ihn zudem Gründer der Marke Matilde. Die Einführung von Dominican Estates ist nicht datiert; Cigarworld.de führt die Marke seit dem 28. September 2005 in seinem Katalog.

Die einzige Mischung vereint ein Deckblatt Connecticut Shade, ein amerikanisches Umblatt Broadleaf und eine Einlage aus kolumbianischen und dominikanischen Tabaken, von milder Stärke, so Cigarworld.de; sie gibt es in zehn Vitolas, von Petit Corona bis Churchill, mit einer Short Magnum und einer Titan im Cepo 60 sowie einer Corona im Glastubus.

José A. Seijas starb 2024 im Alter von 74 Jahren, so Halfwheel; wer die Marke nach ihm übernahm, wird nicht gesagt. Im September 2026 verkauft Cigarworld.de sie noch.',
        '[{"name":"Dominican Estates","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"Deckblatt Connecticut Shade, amerikanisches Umblatt Broadleaf und kolumbianische und dominikanische Einlage, von milder Stärke, in zehn Vitolas, so Cigarworld.de."}]',
        'Dominican Estates是José A. Seijas的品牌，据Cigarworld.de介绍，他是位于多米尼加共和国拉罗马纳的Tabacalera de García的生产主管，该网站还将2009年的VegaFina Limitada归于他名下；Halfwheel称他长期执掌这家工厂，并称他为Matilde品牌的创始人。Dominican Estates的推出日期未标明；Cigarworld.de自2005年9月28日起一直将其列入目录。

该单一配方融合了Connecticut shade茄衣、美国broadleaf茄套，以及哥伦比亚与多米尼加烟叶的茄芯，力度温和，据Cigarworld.de介绍；共有十种规格，从Petit Corona到Churchill，其中有一款Short Magnum、一款cepo 60的Titan，以及一款玻璃管装的Corona。

José A. Seijas于2024年去世，享年74岁，据Halfwheel介绍；此后由谁接手该品牌，未有说明。2026年9月，Cigarworld.de仍在销售该品牌。',
        '[{"name":"Dominican Estates","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"Connecticut shade茄衣，美国broadleaf茄套，哥伦比亚与多米尼加茄芯，力度温和，共十种规格，据Cigarworld.de介绍。"}]',
        'Dominican Estates هي علامة José A. Seijas، رئيس الإنتاج في Tabacalera de García، في لا رومانا بجمهورية الدومينيكان، بحسب Cigarworld.de، الذي ينسب إليه أيضًا VegaFina Limitada لعام 2009؛ وHalfwheel، الذي يقول إنه ظلّ طويلًا على رأس هذا المصنع، يسمّيه أيضًا مؤسسًا لعلامة Matilde. ولم يُؤرَّخ إطلاق Dominican Estates؛ ويُدرجها Cigarworld.de في كتالوجه منذ 28 سبتمبر 2005.

يجمع المزيج الوحيد بين غلاف Connecticut shade ورباط broadleaf أمريكي وحشوة من تبغ كولومبي ودومينيكي، بقوة خفيفة، بحسب Cigarworld.de؛ ويتوفر في عشرة مقاسات، من Petit Corona إلى Churchill، مع مقاس Short Magnum ومقاس Titan من cepo 60 ومقاس Corona في أنبوب زجاجي.

توفي José A. Seijas عام 2024 عن 74 عامًا، بحسب Halfwheel؛ ولم يُذكر من تولّى العلامة بعده. وفي سبتمبر 2026، لا يزال Cigarworld.de يبيعها.',
        '[{"name":"Dominican Estates","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade","vitolas":[],"story":"غلاف Connecticut shade، ورباط broadleaf أمريكي، وحشوة كولومبية ودومينيكية، خفيف القوة، في عشرة مقاسات، بحسب Cigarworld.de."}]')
