-- ── Dos Jotas ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Dos Jotas',
        'dominican',
        '1999 — Juan Ernesto Jiménez, Rép. dominicaine',
        'Fabrique de Chico Rivas, Tamboril (Rép. dominicaine) — selon Momentohumo et André Dias ; la maison ne la nomme pas',
        'dosjotas.do « Dos Jotas Cigars » (site de la maison, en anglais, lu le 30 septembre 2026 : quatre lignes, Prime, Rise, Infinity et Diarios ; fraternité de plus de vingt-cinq ans ; tabac dominicain de la vallée du Cibao ; aucune fabrique nommée ; Rise édition limitée, vieillie plus de quatre ans, force moyenne ; Infinity vieillie plus d''un an en chambre d''affinage, cigare léger) ; dosjotas.do « Dos Jotas Prime » (site de la maison, lu le 30 septembre 2026 : cigare de boutique roulé à la main, assemblage de sept tabacs, force moyenne à soutenue ; Belicoso, Toro, Double Robusto) ; momentohumo.com « Hoy toca… DOS JOTAS Infinity Robusto » (11 février 2022, en espagnol : marque née en 1999 lors d''une visite à la fabrique de Chico Rivas, assembleur d''une quatrième génération de tabaqueros ; fondateur Juan Ernesto Jiménez, associé à l''avocat José Carlos Monagas, ami d''école ; les deux J de Juan et José ; Infinity en cape Habana 92, sous-cape corojo, tripe viso et ligero corojo, tabacs dominicains) ; andredias95.com « 729. Dos Jotas Infinity Robusto » (26 mars 2023, carnet de dégustation d''André Dias : fabrique Chico Rivas, Tamboril ; Juan Ernesto Jiménez propriétaire de Dos Jotas Cigars) ; halfwheel.com « PCA 2025: Dos Jotas » (2025, lue par son titre)',
        NULL,
        'Dos Jotas naît en 1999 en République dominicaine, lors de la visite d''une fabrique, celle de Chico Rivas, assembleur d''une quatrième génération de tabaqueros, dit Momentohumo : son fondateur, Juan Ernesto Jiménez, s''associe à un ami d''école, l''avocat José Carlos Monagas, et les deux J, de Juan et de José, donnent son nom à la marque. La maison dit ses cigares faits par une fraternité de plus de vingt-cinq ans, en tabac dominicain de la vallée du Cibao, et ne nomme pas sa fabrique ; le carnet de dégustation d''André Dias la situe chez Chico Rivas, à Tamboril.

En septembre 2026, le catalogue compte quatre lignes, dit la maison : Prime, un cigare de boutique à l''assemblage de sept tabacs, de force moyenne à soutenue, en Belicoso, Toro et Double Robusto ; Rise, une édition limitée roulée à la main et vieillie plus de quatre ans, de force moyenne ; Infinity, vieillie plus d''un an en chambre d''affinage et présentée comme légère ; et Diarios, que la maison ne détaille pas. Momentohumo décrit l''Infinity sous une cape Habana 92 dominicaine, sur une sous-cape et une tripe de corojo dominicain.

Halfwheel a consacré un article à Dos Jotas lors du salon professionnel PCA de 2025.',
        '[{"name":"Prime","color":"#6B4226","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"Cigare de boutique roulé à la main, à l''assemblage de sept tabacs, de force moyenne à soutenue, en Belicoso, Toro et Double Robusto, dit la maison."},{"name":"Rise","color":"#A0522D","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"Édition limitée roulée à la main et vieillie plus de quatre ans, de force moyenne, dit la maison."},{"name":"Infinity","color":"#C9A96E","force":"Mild","wrapper":"Habana 92 dominicaine","vitolas":[],"story":"Vieillie plus d''un an en chambre d''affinage et présentée comme légère, dit la maison ; sous-cape et tripe de corojo dominicain, dit Momentohumo."},{"name":"Diarios","color":"#A0522D","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"La maison ne détaille ni sa cape ni sa force."}]',
        'Dos Jotas was born in 1999 in the Dominican Republic, during a visit to a factory, that of Chico Rivas, a blender from a fourth generation of tabaqueros, says Momentohumo: its founder, Juan Ernesto Jiménez, partnered with a school friend, the lawyer José Carlos Monagas, and the two Js, of Juan and of José, gave the brand its name. The house says its cigars are made by a brotherhood of more than twenty-five years, in Dominican tobacco from the Cibao Valley, and does not name its factory; André Dias''s tasting notebook places it at Chico Rivas, in Tamboril.

In September 2026, the catalogue comprises four lines, says the house: Prime, a boutique cigar with a blend of seven tobaccos, of medium to full strength, in Belicoso, Toro and Double Robusto; Rise, a limited edition rolled by hand and aged for more than four years, of medium strength; Infinity, aged for more than a year in an ageing chamber and presented as light; and Diarios, which the house does not detail. Momentohumo describes the Infinity under a Dominican Habana 92 wrapper, over a binder and filler of Dominican corojo.

Halfwheel devoted an article to Dos Jotas at the PCA trade show in 2025.',
        '[{"name":"Prime","color":"#6B4226","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"Hand-rolled boutique cigar with a blend of seven tobaccos, of medium to full strength, in Belicoso, Toro and Double Robusto, says the house."},{"name":"Rise","color":"#A0522D","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"Limited edition rolled by hand and aged for more than four years, of medium strength, says the house."},{"name":"Infinity","color":"#C9A96E","force":"Mild","wrapper":"Dominican Habana 92","vitolas":[],"story":"Aged for more than a year in an ageing chamber and presented as light, says the house; binder and filler of Dominican corojo, says Momentohumo."},{"name":"Diarios","color":"#A0522D","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"The house details neither its wrapper nor its strength."}]',
        'Dos Jotas nace en 1999 en la República Dominicana, durante la visita a una fábrica, la de Chico Rivas, mezclador de una cuarta generación de tabaqueros, dice Momentohumo: su fundador, Juan Ernesto Jiménez, se asocia con un amigo de escuela, el abogado José Carlos Monagas, y las dos J, de Juan y de José, dan su nombre a la marca. La casa dice que sus puros los hace una hermandad de más de veinticinco años, con tabaco dominicano del valle del Cibao, y no nombra su fábrica; el cuaderno de cata de André Dias la sitúa en la fábrica de Chico Rivas, en Tamboril.

En septiembre de 2026, el catálogo cuenta con cuatro líneas, dice la casa: Prime, un puro boutique con una mezcla de siete tabacos, de fuerza media a intensa, en Belicoso, Toro y Double Robusto; Rise, una edición limitada liada a mano y añejada más de cuatro años, de fuerza media; Infinity, añejada más de un año en cámara de añejamiento y presentada como ligera; y Diarios, que la casa no detalla. Momentohumo describe la Infinity bajo una capa Habana 92 dominicana, sobre un capote y una tripa de corojo dominicano.

Halfwheel dedicó un artículo a Dos Jotas durante la feria profesional PCA de 2025.',
        '[{"name":"Prime","color":"#6B4226","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"Puro boutique liado a mano, con una mezcla de siete tabacos, de fuerza media a intensa, en Belicoso, Toro y Double Robusto, dice la casa."},{"name":"Rise","color":"#A0522D","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"Edición limitada liada a mano y añejada más de cuatro años, de fuerza media, dice la casa."},{"name":"Infinity","color":"#C9A96E","force":"Mild","wrapper":"Habana 92 dominicana","vitolas":[],"story":"Añejada más de un año en cámara de añejamiento y presentada como ligera, dice la casa; capote y tripa de corojo dominicano, dice Momentohumo."},{"name":"Diarios","color":"#A0522D","force":null,"wrapper":"No divulgada","vitolas":[],"story":"La casa no detalla ni su capa ni su fuerza."}]',
        'Dos Jotas entsteht 1999 in der Dominikanischen Republik beim Besuch einer Fabrik, der von Chico Rivas, Blender einer vierten Generation von Tabaqueros, so Momentohumo: Der Gründer der Marke, Juan Ernesto Jiménez, tut sich mit einem Schulfreund, dem Rechtsanwalt José Carlos Monagas, zusammen, und die beiden J, von Juan und von José, geben der Marke ihren Namen. Das Haus sagt, seine Zigarren würden von einer mehr als fünfundzwanzig Jahre alten Bruderschaft gefertigt, aus dominikanischem Tabak des Cibao-Tals, und nennt seine Fabrik nicht; das Verkostungsprotokoll von André Dias verortet sie bei Chico Rivas in Tamboril.

Im September 2026 umfasst der Katalog vier Linien, so das Haus: Prime, eine Boutique-Zigarre mit einer Mischung aus sieben Tabaken, von mittlerer bis kräftiger Stärke, als Belicoso, Toro und Double Robusto; Rise, eine von Hand gerollte Limited Edition, mehr als vier Jahre gereift, von mittlerer Stärke; Infinity, mehr als ein Jahr in einer Reifekammer gereift und als leicht vorgestellt; und Diarios, das das Haus nicht näher beschreibt. Momentohumo beschreibt die Infinity mit einem dominikanischen Deckblatt Habana 92, auf Umblatt und Einlage aus dominikanischem Corojo.

Halfwheel widmete Dos Jotas auf der Fachmesse PCA 2025 einen Artikel.',
        '[{"name":"Prime","color":"#6B4226","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Von Hand gerollte Boutique-Zigarre mit einer Mischung aus sieben Tabaken, von mittlerer bis kräftiger Stärke, als Belicoso, Toro und Double Robusto, so das Haus."},{"name":"Rise","color":"#A0522D","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Von Hand gerollte Limited Edition, mehr als vier Jahre gereift, von mittlerer Stärke, so das Haus."},{"name":"Infinity","color":"#C9A96E","force":"Mild","wrapper":"Habana 92 aus der Dominikanischen Republik","vitolas":[],"story":"Mehr als ein Jahr in einer Reifekammer gereift und als leicht vorgestellt, so das Haus; Umblatt und Einlage aus dominikanischem Corojo, so Momentohumo."},{"name":"Diarios","color":"#A0522D","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Das Haus beschreibt weder das Deckblatt noch die Stärke näher."}]',
        'Dos Jotas于1999年诞生于多米尼加共和国，起因是一次工厂参观，所访问的是Chico Rivas的工厂，他是出身于第四代tabaqueros的调配师，据Momentohumo介绍：品牌创始人Juan Ernesto Jiménez与学生时代的朋友、律师José Carlos Monagas合伙，两个J分别来自Juan与José，为品牌命名。品牌方称其雪茄由一份超过二十五年的兄弟情谊打造，使用来自锡瓦奥谷地的多米尼加烟叶，并未说明其工厂名称；André Dias的品鉴笔记将该工厂定位于Chico Rivas处，地点在坦博里尔。

2026年9月，据品牌方介绍，目录共有四个系列：Prime，一款精品雪茄，由七种烟叶调配而成，力度中等至浓郁，规格有Belicoso、Toro与Double Robusto；Rise，限量版，手工卷制，陈化超过四年，力度中等；Infinity，在陈化室中陈化超过一年，并被描述为力度轻；以及Diarios，品牌方未作详细说明。Momentohumo称Infinity采用多米尼加Habana 92茄衣，覆于多米尼加corojo茄套与茄芯之上。

在2025年的PCA行业展会上，Halfwheel发表了一篇关于Dos Jotas的文章。',
        '[{"name":"Prime","color":"#6B4226","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"手工卷制的精品雪茄，由七种烟叶调配而成，力度中等至浓郁，规格有Belicoso、Toro与Double Robusto，据品牌方介绍。"},{"name":"Rise","color":"#A0522D","force":"Medium","wrapper":"未公开","vitolas":[],"story":"手工卷制的限量版，陈化超过四年，力度中等，据品牌方介绍。"},{"name":"Infinity","color":"#C9A96E","force":"Mild","wrapper":"多米尼加Habana 92","vitolas":[],"story":"在陈化室中陈化超过一年，并被描述为力度轻，据品牌方介绍；茄套与茄芯为多米尼加corojo，据Momentohumo介绍。"},{"name":"Diarios","color":"#A0522D","force":null,"wrapper":"未公开","vitolas":[],"story":"品牌方既未详述其茄衣，也未详述其力度。"}]',
        'نشأت Dos Jotas عام 1999 في جمهورية الدومينيكان، خلال زيارة لمصنع هو مصنع Chico Rivas، الخلّاط المنحدر من الجيل الرابع من tabaqueros، بحسب Momentohumo: تشارك مؤسسها Juan Ernesto Jiménez مع صديق من أيام المدرسة، هو المحامي José Carlos Monagas، ويمنح الحرفان J، حرف Juan وحرف José، العلامة اسمها. وتقول الدار إن سيجارها تصنعه أخوّة عمرها ما يزيد على خمسة وعشرين عامًا، من تبغ دومينيكي من وادي سيباو، ولا تسمّي مصنعها؛ ويحدّد دفتر تذوّق André Dias موقع هذا المصنع لدى Chico Rivas في تامبوريل.

في سبتمبر 2026، يضمّ الكتالوج أربعة خطوط، بحسب الدار: Prime، سيجار بوتيك بمزيج من سبعة أنواع من التبغ، بقوة متوسطة إلى قوية، بمقاسات Belicoso وToro وDouble Robusto؛ وRise، إصدار محدود يُلفّ يدويًا ومعتَّق ما يزيد على أربع سنوات، بقوة متوسطة؛ وInfinity، معتَّق ما يزيد على عام في غرفة تعتيق ومقدَّم على أنه خفيف؛ وDiarios، الذي لا تفصّله الدار. ويصف Momentohumo خط Infinity بغلاف Habana 92 دومينيكي، على رباط وحشوة من corojo دومينيكي.

وخصّص Halfwheel مقالًا عن Dos Jotas خلال معرض PCA المهني لعام 2025.',
        '[{"name":"Prime","color":"#6B4226","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"سيجار بوتيك يُلفّ يدويًا، بمزيج من سبعة أنواع من التبغ، بقوة متوسطة إلى قوية، بمقاسات Belicoso وToro وDouble Robusto، بحسب الدار."},{"name":"Rise","color":"#A0522D","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"إصدار محدود يُلفّ يدويًا ومعتَّق ما يزيد على أربع سنوات، بقوة متوسطة، بحسب الدار."},{"name":"Infinity","color":"#C9A96E","force":"Mild","wrapper":"Habana 92 دومينيكي","vitolas":[],"story":"معتَّق ما يزيد على عام في غرفة تعتيق ومقدَّم على أنه خفيف، بحسب الدار؛ ورباط وحشوة من corojo دومينيكي، بحسب Momentohumo."},{"name":"Diarios","color":"#A0522D","force":null,"wrapper":"غير معلن","vitolas":[],"story":"لا تفصّل الدار غلافه ولا قوته."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Tambor Essence ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Tambor Essence',
        'nicaragua',
        'Non précisée — Víctor Calvo, Estelí',
        'Usine propre — Tabacalera Tambor (Víctor Calvo), Estelí',
        'cigarworld.de « Tambor Essence Blend Capussino » (lu le 30 septembre 2026, en allemand : fabricant Tambor de Nicaragua ; totalmente a mano, tripe longue ; cape, sous-cape et tripe du Nicaragua ; aromatisé, force moyenne ; Corona de 6 pouces, cepo 44 ; variantes Capussino et Espresso ; importateur StarkeZigarren, Berlin) ; portal.amelica.org « Étude sur le procédé de production et d''exportation de l''Empresa Tabacalera Tambor de Nicaragua S.A. » (FAREM-Estelí, en espagnol, 2018-2019 : ouverture de la fabrique en 1996 au Costa Rica sous le nom de Tabacalera Cachí, fermeture et installation à Estelí fin septembre 2001, passage à Víctor Calvo en mai 2002)',
        NULL,
        'Tambor Essence est une ligne de cigares aromatisés roulés entièrement à la main par la Tabacalera Tambor de Nicaragua, à Estelí, dit Cigarworld.de. Une étude de la FAREM-Estelí, en espagnol, situe la naissance de la fabrique en 1996 au Costa Rica, sous le nom de Tabacalera Cachí ; elle y ferme en 2001, s''installe à Estelí fin septembre de la même année et passe en mai 2002 à Víctor Calvo.

Deux arômes composent la ligne, Cappuccino et Espresso, dit Cigarworld.de, qui donne le Cappuccino à cape, sous-cape et tripe nicaraguayennes, en tripe longue, de force moyenne, en Corona de six pouces pour un cepo 44.

En septembre 2026, Cigarworld.de vend la ligne, importée en Allemagne par StarkeZigarren, à Berlin.',
        '[{"name":"Cappuccino","color":"#A0522D","force":"Medium","wrapper":"Nicaragua","vitolas":[],"story":"Arôme de cappuccino sur un puro nicaraguayen roulé à la main, en Corona, de force moyenne, dit Cigarworld.de."},{"name":"Espresso","color":"#6B4226","force":null,"wrapper":"Nicaragua","vitolas":[],"story":"Second arôme de la ligne, celui de l''espresso, dit Cigarworld.de."}]',
        'Tambor Essence is a line of flavoured cigars rolled entirely by hand by Tabacalera Tambor de Nicaragua, in Estelí, says Cigarworld.de. A study by FAREM-Estelí, in Spanish, places the birth of the factory in 1996 in Costa Rica, under the name Tabacalera Cachí; it closed there in 2001, moved to Estelí at the end of September of the same year and passed to Víctor Calvo in May 2002.

Two flavours make up the line, Cappuccino and Espresso, says Cigarworld.de, which lists the Cappuccino with a Nicaraguan wrapper, binder and filler, as a longfiller, of medium strength, in a six-inch Corona with cepo 44.

In September 2026, Cigarworld.de sells the line, imported into Germany by StarkeZigarren, in Berlin.',
        '[{"name":"Cappuccino","color":"#A0522D","force":"Medium","wrapper":"Nicaragua","vitolas":[],"story":"Cappuccino flavour on a hand-rolled Nicaraguan puro, in Corona, of medium strength, says Cigarworld.de."},{"name":"Espresso","color":"#6B4226","force":null,"wrapper":"Nicaragua","vitolas":[],"story":"Second flavour of the line, the espresso one, says Cigarworld.de."}]',
        'Tambor Essence es una línea de puros aromatizados liados enteramente a mano por la Tabacalera Tambor de Nicaragua, en Estelí, dice Cigarworld.de. Un estudio de la FAREM-Estelí, en español, sitúa el nacimiento de la fábrica en 1996 en Costa Rica, con el nombre de Tabacalera Cachí; allí cierra en 2001, se instala en Estelí a finales de septiembre del mismo año y pasa en mayo de 2002 a Víctor Calvo.

Dos aromas componen la línea, Cappuccino y Espresso, dice Cigarworld.de, que presenta el Cappuccino con capa, capote y tripa nicaragüenses, en longfiller, de fuerza media, en Corona de seis pulgadas con cepo 44.

En septiembre de 2026, Cigarworld.de vende la línea, importada a Alemania por StarkeZigarren, en Berlín.',
        '[{"name":"Cappuccino","color":"#A0522D","force":"Medium","wrapper":"Nicaragua","vitolas":[],"story":"Aroma de cappuccino sobre un puro nicaragüense liado a mano, en Corona, de fuerza media, dice Cigarworld.de."},{"name":"Espresso","color":"#6B4226","force":null,"wrapper":"Nicaragua","vitolas":[],"story":"Segundo aroma de la línea, el del espresso, dice Cigarworld.de."}]',
        'Tambor Essence ist eine Linie aromatisierter Zigarren, die von der Tabacalera Tambor de Nicaragua in Estelí vollständig von Hand gerollt werden, so Cigarworld.de. Eine Studie der FAREM-Estelí, auf Spanisch, verortet die Entstehung der Fabrik 1996 in Costa Rica unter dem Namen Tabacalera Cachí; dort schließt sie 2001, siedelt sich Ende September desselben Jahres in Estelí an und geht im Mai 2002 an Víctor Calvo über.

Zwei Aromen bilden die Linie, Cappuccino und Espresso, so Cigarworld.de, das den Cappuccino mit nicaraguanischem Deckblatt, Umblatt und nicaraguanischer Einlage beschreibt, als Longfiller, von mittlerer Stärke, als Corona von sechs Zoll mit Cepo 44.

Im September 2026 verkauft Cigarworld.de die Linie, die von StarkeZigarren in Berlin nach Deutschland importiert wird.',
        '[{"name":"Cappuccino","color":"#A0522D","force":"Medium","wrapper":"Nicaragua","vitolas":[],"story":"Cappuccino-Aroma auf einem von Hand gerollten nicaraguanischen Puro, als Corona, von mittlerer Stärke, so Cigarworld.de."},{"name":"Espresso","color":"#6B4226","force":null,"wrapper":"Nicaragua","vitolas":[],"story":"Zweites Aroma der Linie, das des Espresso, so Cigarworld.de."}]',
        'Tambor Essence是由位于埃斯特利的Tabacalera Tambor de Nicaragua完全手工卷制的加香雪茄系列，据Cigarworld.de介绍。FAREM-Estelí的一项西班牙语研究，将该工厂的诞生定在1996年的哥斯达黎加，当时名为Tabacalera Cachí；该厂于2001年在当地关闭，同年9月底迁至埃斯特利，并于2002年5月转归Víctor Calvo。

该系列由两种香气构成，即Cappuccino与Espresso，据Cigarworld.de介绍；该网站将Cappuccino列为茄衣、茄套与茄芯均产自尼加拉瓜的longfiller，力度中等，规格为六英寸的Corona，cepo 44。

2026年9月，Cigarworld.de销售该系列，由位于柏林的StarkeZigarren进口至德国。',
        '[{"name":"Cappuccino","color":"#A0522D","force":"Medium","wrapper":"尼加拉瓜","vitolas":[],"story":"带卡布奇诺香气的手工卷制尼加拉瓜puro，Corona规格，力度中等，据Cigarworld.de介绍。"},{"name":"Espresso","color":"#6B4226","force":null,"wrapper":"尼加拉瓜","vitolas":[],"story":"该系列的第二种香气，即意式浓缩咖啡香，据Cigarworld.de介绍。"}]',
        'Tambor Essence خط من السيجار المنكَّه يُلفّ بالكامل يدويًا على يد Tabacalera Tambor de Nicaragua في إستيلي، بحسب Cigarworld.de. وترجع دراسة صادرة عن FAREM-Estelí، بالإسبانية، نشأة المصنع إلى عام 1996 في كوستاريكا، باسم Tabacalera Cachí؛ وأُغلق هناك عام 2001، واستقرّ في إستيلي في أواخر سبتمبر من العام نفسه، وانتقل في مايو 2002 إلى Víctor Calvo.

يتكوّن الخط من نكهتين، Cappuccino وEspresso، بحسب Cigarworld.de، الذي يصف Cappuccino بغلاف ورباط وحشوة نيكاراغوية، من نوع longfiller، بقوة متوسطة، في مقاس Corona بطول ست بوصات وcepo 44.

وفي سبتمبر 2026، يبيع Cigarworld.de الخط، المستورد إلى ألمانيا من قِبل StarkeZigarren في برلين.',
        '[{"name":"Cappuccino","color":"#A0522D","force":"Medium","wrapper":"نيكاراغوا","vitolas":[],"story":"نكهة الكابتشينو على puro نيكاراغوي مُلفوف يدويًا، بمقاس Corona، بقوة متوسطة، بحسب Cigarworld.de."},{"name":"Espresso","color":"#6B4226","force":null,"wrapper":"نيكاراغوا","vitolas":[],"story":"النكهة الثانية في الخط، وهي نكهة الإسبريسو، بحسب Cigarworld.de."}]')
