-- ── Teatro del Mundo ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Teatro del Mundo',
        'nicaragua',
        'Non précisée — August Schuster, Bünde',
        'Nicaragua — la maison ne nomme pas sa fabrique',
        'tabakhausschall.de « Teatro del Mundo – Zigarre des Monats » (1er juin 2023, en allemand, lu le 30 septembre 2026 : une création de la maison August Schuster, à Bünde ; arômes de chocolat) ; falkum.de « Teatro del Mundo Zigarre Nicaragua » (lu le 30 septembre 2026, en allemand : importateur August Schuster GmbH & Co KG, Bünde ; cape et sous-cape du Nicaragua, tripe non détaillée ; arômes de chocolat dominants ; masques vénitiens sur la seconde bague et la boîte, inspirés du carnaval de Venise ; Robusto de 126 mm, cepo 50 ; force moyenne) ; schustercigars.de « Wir » (septembre 2026, en allemand : société inscrite au registre du commerce le 27 septembre 1909 par August Schuster, dans la continuité d''une fabrique ouverte en 1897 par Hermann Schuster) ; cigarworld.de « Teatro del Mundo Special Longfiller Robusto » (lu le 30 septembre 2026, en anglais : totalmente a mano ; cape, sous-cape et tripe du Nicaragua ; aromatisé ; force moyenne ; Robusto de 5 pouces, cepo 50 ; importateur August Schuster GmbH & Co KG, Bünde ; aucune fabrique nommée) ; peterheinrichs.de « Teatro del Mundo » (septembre 2026, en allemand : confirme la présence au catalogue, origine Nicaragua, aucune fabrique nommée)',
        NULL,
        'Teatro del Mundo est une création de la maison August Schuster, à Bünde, en Rhénanie-du-Nord-Westphalie, dit Tabakhaus Schall en juin 2023 ; Cigarworld.de et Falkum.de donnent Schuster pour importateur. La firme est établie le 27 septembre 1909 par August Schuster, dans la continuité d''une fabrique ouverte en 1897 par Hermann Schuster, dit-elle sur son site. La maison ne nomme pas la fabrique nicaraguayenne qui roule Teatro del Mundo.

La ligne tient en un seul cigare, un puro nicaraguayen roulé entièrement à la main et aromatisé, vendu en Robusto de cinq pouces pour un cepo 50, de force moyenne, dit Cigarworld.de. Falkum.de le dit dominé par des arômes de chocolat et rattache son habillage au carnaval de Venise : des masques vénitiens ornent la seconde bague et la boîte.

En septembre 2026, Cigarworld.de, Falkum.de et Peterheinrichs.de le vendent encore.',
        '[{"name":"Teatro del Mundo","color":"#A0522D","force":"Medium","wrapper":"Nicaragua","vitolas":[],"story":"Puro nicaraguayen aromatisé, en Robusto, dominé par des arômes de chocolat, dit Falkum.de."}]',
        'Teatro del Mundo is a creation of the August Schuster house, in Bünde, in North Rhine-Westphalia, says Tabakhaus Schall in June 2023; Cigarworld.de and Falkum.de give Schuster as the importer. The firm was established on 27 September 1909 by August Schuster, as a continuation of a factory opened in 1897 by Hermann Schuster, it says on its website. The house does not name the Nicaraguan factory that rolls Teatro del Mundo.

The line consists of a single cigar, a Nicaraguan puro rolled entirely by hand and flavoured, sold as a five-inch Robusto with cepo 50, of medium strength, says Cigarworld.de. Falkum.de says it is dominated by chocolate flavours and ties its presentation to the Carnival of Venice: Venetian masks adorn the second band and the box.

In September 2026, Cigarworld.de, Falkum.de and Peterheinrichs.de still sell it.',
        '[{"name":"Teatro del Mundo","color":"#A0522D","force":"Medium","wrapper":"Nicaragua","vitolas":[],"story":"Flavoured Nicaraguan puro, in Robusto, dominated by chocolate flavours, says Falkum.de."}]',
        'Teatro del Mundo es una creación de la casa August Schuster, en Bünde, en Renania del Norte-Westfalia, dice Tabakhaus Schall en junio de 2023; Cigarworld.de y Falkum.de dan a Schuster como importador. La firma fue establecida el 27 de septiembre de 1909 por August Schuster, en la continuidad de una fábrica abierta en 1897 por Hermann Schuster, dice en su sitio web. La casa no nombra la fábrica nicaragüense que lía Teatro del Mundo.

La línea se reduce a un solo puro, un puro nicaragüense liado enteramente a mano y aromatizado, vendido en Robusto de cinco pulgadas con cepo 50, de fuerza media, dice Cigarworld.de. Falkum.de lo dice dominado por aromas de chocolate y vincula su presentación con el carnaval de Venecia: máscaras venecianas adornan la segunda anilla y la caja.

En septiembre de 2026, Cigarworld.de, Falkum.de y Peterheinrichs.de todavía lo venden.',
        '[{"name":"Teatro del Mundo","color":"#A0522D","force":"Medium","wrapper":"Nicaragua","vitolas":[],"story":"Puro nicaragüense aromatizado, en Robusto, dominado por aromas de chocolate, dice Falkum.de."}]',
        'Teatro del Mundo ist eine Kreation des Hauses August Schuster in Bünde in Nordrhein-Westfalen, so Tabakhaus Schall im Juni 2023; Cigarworld.de und Falkum.de nennen Schuster als Importeur. Die Firma wurde am 27. September 1909 von August Schuster gegründet, in Fortführung einer 1897 von Hermann Schuster eröffneten Fabrik, so die Firma selbst auf ihrer Website. Das Haus nennt die nicaraguanische Fabrik, die Teatro del Mundo rollt, nicht.

Die Linie besteht aus einer einzigen Zigarre, einem vollständig von Hand gerollten, aromatisierten nicaraguanischen Puro, der als Robusto von fünf Zoll mit Cepo 50 verkauft wird, von mittlerer Stärke, so Cigarworld.de. Falkum.de beschreibt ihn als von Schokoladenaromen dominiert und bringt seine Aufmachung mit dem Karneval von Venedig in Verbindung: Venezianische Masken zieren die zweite Bauchbinde und die Kiste.

Im September 2026 verkaufen Cigarworld.de, Falkum.de und Peterheinrichs.de ihn noch.',
        '[{"name":"Teatro del Mundo","color":"#A0522D","force":"Medium","wrapper":"Nicaragua","vitolas":[],"story":"Aromatisierter nicaraguanischer Puro, als Robusto, von Schokoladenaromen dominiert, so Falkum.de."}]',
        'Teatro del Mundo是位于北莱茵-威斯特法伦州宾德的August Schuster商行的创制之作，据Tabakhaus Schall在2023年6月介绍；Cigarworld.de与Falkum.de将Schuster列为进口商。该公司由August Schuster于1909年9月27日设立，延续了Hermann Schuster于1897年开办的一家工厂，据该公司网站介绍。该商行未透露卷制Teatro del Mundo的尼加拉瓜工厂的名称。

该系列只有一款雪茄，即完全手工卷制的加香尼加拉瓜puro，以五英寸的Robusto规格销售，cepo 50，力度中等，据Cigarworld.de介绍。Falkum.de称其以巧克力香气为主导，并将其外观包装与威尼斯狂欢节联系起来：威尼斯面具装饰着第二枚雪茄环和雪茄盒。

2026年9月，Cigarworld.de、Falkum.de与Peterheinrichs.de仍在销售该雪茄。',
        '[{"name":"Teatro del Mundo","color":"#A0522D","force":"Medium","wrapper":"尼加拉瓜","vitolas":[],"story":"加香的尼加拉瓜puro，规格为Robusto，以巧克力香气为主导，据Falkum.de介绍。"}]',
        'Teatro del Mundo من ابتكار دار August Schuster في Bünde، في شمال الراين-وستفاليا، بحسب Tabakhaus Schall في يونيو 2023؛ ويذكر Cigarworld.de وFalkum.de أن المستورد هو Schuster. وأُنشئت الشركة في 27 سبتمبر 1909 على يد August Schuster، امتدادًا لمصنع افتتحه Hermann Schuster عام 1897، بحسب ما تقوله على موقعها الإلكتروني. ولا تسمّي الدار المصنع النيكاراغوي الذي يلفّ Teatro del Mundo.

يقتصر الخط على سيجار واحد، هو puro نيكاراغوي مُلفوف بالكامل يدويًا ومنكَّه، يُباع بمقاس Robusto طوله خمس بوصات وcepo 50، بقوة متوسطة، بحسب Cigarworld.de. ويصفه Falkum.de بأنه تغلب عليه نكهات الشوكولاتة، ويربط مظهره بكرنفال البندقية: تزيّن أقنعة البندقية الحلقة الثانية والعلبة.

وفي سبتمبر 2026، لا يزال يبيعه Cigarworld.de وFalkum.de وPeterheinrichs.de.',
        '[{"name":"Teatro del Mundo","color":"#A0522D","force":"Medium","wrapper":"نيكاراغوا","vitolas":[],"story":"puro نيكاراغوي منكَّه، بمقاس Robusto، تغلب عليه نكهات الشوكولاتة، بحسب Falkum.de."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

