nic":false},{"name":"Bauza","desc":"Marque cubaine relancée en 1990 (Fuente/Boruchin), roulée à la fabrique Arturo Fuente, Santiago.","iconic":false},{"name":"Butera","desc":"1993 — Michael Butera ; marque d''Altadis U.S.A., deux lignes sous cape Connecticut Shade.","iconic":false},{"name":"Hemmys","desc":"2019 — Hemmy Garcia (Berlin) ; roulée chez ABAM, à Santo Domingo, en trois lignes.","iconic":false},{"name":"German Engineered Cigars","desc":"2016 — Hambourg ; roulée chez Intercigar (Rép. dominicaine) et chez Tabacalera Tambor (Nicaragua).","iconic":false},{"name":"Dalay","desc":"Salih Dalay, Sarrebruck ; roulée à Zauberberg (Santiago) et chez Luciano Cigars (Estelí).","iconic":false},{"name":"Casa de Garcia","desc":"Altadis U.S.A. — Tabacalera de García, La Romana ; six lignes, dont deux Centenario façonnées au Nicaragua.","iconic":false},{"name":"Dominican Estates","desc":"José A. Seijas, chef de fabrication de la Tabacalera de García — assemblage unique, dix vitolas, La Romana.","iconic":false},{"name":"Dos Jotas","desc":"Née en 1999 (Juan Ernesto Jiménez) ; fabrique de Chico Rivas, à Tamboril, selon Momentohumo et André Dias.","iconic":false}]' WHERE `id` = 'dominican';

