INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` ELSE b.`gamme` END), 'machine', NOW()
  FROM `brands` b
  JOIN (SELECT 'history' champ UNION ALL SELECT 'gamme') c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE b.`name` IN ('Hemmys','El Galan','German Engineered Cigars','H.R.','Helvada','Dalay','Legado','Omar Rodriguez','Spartanos','Tabacosta','Casa de Garcia','Dominican Estates','Dos Jotas','Tambor Essence','Teatro del Mundo')
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `statut` = 'machine', `maj` = NOW();

DELETE FROM `moderation_log` WHERE `acteur_nom` = 'migration 244';
INSERT INTO `moderation_log`
  (`acteur_id`, `acteur_nom`, `portee`, `action`, `cible_type`, `cible_id`, `detail`)
VALUES
  (NULL,'migration 244','systeme','recensement_8_fiches','marque',0,
   'dominican : Hemmys, German Engineered Cigars, Dalay, Casa de Garcia, Dominican Estates, Dos Jotas'),
  (NULL,'migration 244','systeme','recensement_8_fiches','marque',0,
   'nicaragua : El Galan, H.R., Helvada, Omar Rodriguez, Spartanos, Tabacosta, Tambor Essence, Teatro del Mundo'),
  (NULL,'migration 244','systeme','recensement_8_fiches','marque',0,
   'honduras : Legado');

SELECT
  (SELECT COUNT(*) FROM `brands` WHERE `name` IN ('Hemmys','El Galan','German Engineered Cigars','H.R.','Helvada','Dalay','Legado','Omar Rodriguez','Spartanos','Tabacosta','Casa de Garcia','Dominican Estates','Dos Jotas','Tambor Essence','Teatro del Mundo')) = 15 AS fiches,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Hemmys"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"German Engineered Cigars"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Dalay"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Casa de Garcia"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Dominican Estates"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Dos Jotas"') FROM `producer_countries` WHERE `id` = 'dominican') AS dominican_annonce,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"El Galan"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"H.R."') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Helvada"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Omar Rodriguez"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Spartanos"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Tabacosta"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Tambor Essence"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Teatro del Mundo"') FROM `producer_countries` WHERE `id` = 'nicaragua') AS nicaragua_annonce,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Legado"') FROM `producer_countries` WHERE `id` = 'honduras') AS honduras_annonce,
  (SELECT COUNT(*) FROM `translation_status` WHERE `entite` = 'brands' AND `entite_id` IN ('Hemmys','El Galan','German Engineered Cigars','H.R.','Helvada','Dalay','Legado','Omar Rodriguez','Spartanos','Tabacosta','Casa de Garcia','Dominican Estates','Dos Jotas','Tambor Essence','Teatro del Mundo')) = 150 AS sceaux,
  (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 244') AS journal_non_tronque;
SELECT COUNT(*) AS marques, SUM(TRIM(COALESCE(`source`,'')) = '') AS sans_source FROM `brands`;
